CREATE OR REPLACE FUNCTION public.fn_ca_tournament_seat_cap(p_tournament_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_variant text;
  v_format text;
  v_cap integer;
BEGIN
  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament not found' USING ERRCODE='P0002';
  END IF;
  v_variant:=lower(COALESCE(NULLIF(v_t.game_type,''),'nlh'));
  v_format:=lower(COALESCE(v_t.variant,''));
  v_cap:=CASE
    WHEN v_format='spin' OR upper(COALESCE(v_t.tournament_type,''))='SPIN'
      THEN 3
    WHEN v_format='sng' OR upper(COALESCE(v_t.tournament_type,''))='SNG'
      THEN LEAST(COALESCE(NULLIF(v_t.max_players,0),6),9)
    ELSE LEAST(COALESCE(NULLIF(v_t.table_size,0),9),10)
  END;
  v_cap:=LEAST(v_cap,CASE v_variant
    WHEN 'plo5' THEN 9
    WHEN 'plo6' THEN 7
    ELSE 10
  END);
  RETURN GREATEST(v_cap,2);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_unregister_tournament_player_exact(p_tournament_id uuid, p_user_id uuid, p_expected_table_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_reg public.tournament_players%ROWTYPE;
  v_ent record;
  v_fee_group record;
  v_settle jsonb;
  v_receipt jsonb;
  v_escrow_before public.tournament_escrow%ROWTYPE;
  v_escrow_after public.tournament_escrow%ROWTYPE;
  v_players_before integer;
  v_rows integer;
  v_seat_number integer;
  v_seats_taken integer;
  v_non_cash_count integer;
  v_wallet_debits numeric:=0;
  v_wallet_refunds_before numeric:=0;
  v_wallet_refunds_after numeric:=0;
  v_entitled_wallet_total numeric:=0;
  v_tranche_total numeric:=0;
  v_refund_prize numeric:=0;
  v_refund_bounty numeric:=0;
  v_refund_fee numeric:=0;
  v_refund_total numeric:=0;
  v_wallet_amount numeric:=0;
  v_ticket_amount numeric:=0;
  v_running_owed numeric:=0;
  v_rake_before numeric:=0;
  v_rake_after numeric:=0;
  v_fees_reversed numeric:=0;
  v_entitlement_ids uuid[]:='{}'::uuid[];
  v_ticket_ids uuid[]:='{}'::uuid[];
  v_credit_ledger_ids uuid[]:='{}'::uuid[];
  v_wallet_transaction_ids uuid[]:='{}'::uuid[];
  v_source_wallet_club_ids uuid[]:='{}'::uuid[];
  v_fee_reversal_ids uuid[]:='{}'::uuid[];
  v_fee_source_rake_record_ids uuid[]:='{}'::uuid[];
  v_fee_entitlement_ids uuid[]:='{}'::uuid[];
  v_fee_reversal_id uuid;
  v_fee_source_count integer:=0;
  v_fee_source_entitlement_count integer:=0;
  v_fee_source_amount numeric:=0;
  v_request_id uuid:=COALESCE(p_request_id,gen_random_uuid());
  v_start_authority text:='scheduled_clock';
  v_launch_completed_at timestamptz;
  v_persisted_hand_exists boolean:=false;
  v_actual_status text;
  v_actual_started_at timestamptz;
  v_unregistered_at timestamptz;
  v_description text:=COALESCE(
    NULLIF(btrim(p_description),''),'Tournament unregistration refund');
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'tournament and player ids are required'
      USING ERRCODE='22004';
  END IF;
  -- DIAMOND PHASE 8: a Diamond entry never rode the chip rails. Every
  -- caller of this authority (the lobby, the seat, the administrator, the
  -- launch) sends it home through its own door before a chip rail is
  -- touched. A caller that named no request id is given one exactly as
  -- this authority mints its own. A seat exit naming a table the player
  -- does not sit at answers not_seated unless its request id is already
  -- settled, in which case the door replays that receipt.
  IF public.fn_poker_diamond_tournament(p_tournament_id) THEN
    IF p_expected_table_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.table_seats s
                        WHERE s.table_id=p_expected_table_id AND s.user_id=p_user_id AND s.left_at IS NULL)
       AND NOT (p_request_id IS NOT NULL AND EXISTS (
                  SELECT 1 FROM public.poker_diamond_tournament_ledger l
                   WHERE l.tournament_id=p_tournament_id AND l.user_id=p_user_id AND l.kind='refund'
                     AND l.request->>'request_id'=p_request_id::text)) THEN
      RETURN jsonb_build_object('ok',false,'reason','not_seated');
    END IF;
    RETURN public.fn_poker_diamond_tournament_unregister(
      p_tournament_id, p_user_id, COALESCE(p_request_id, gen_random_uuid()));
  END IF;
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF v_t.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;

  -- Spins and Heads-Up Sit & Gos are separate products, but both are
  -- seat-first: start_time is only their human fill-window deadline. Neither
  -- product has a scheduled start. Satellite feeders remain outside this
  -- change and retain the existing scheduled-clock contract.
  IF v_t.satellite_target_id IS NULL
     AND upper(COALESCE(v_t.tournament_type::text,''))<>'SATELLITE'
     AND (lower(COALESCE(v_t.variant::text,''))='spin'
       OR upper(COALESCE(v_t.tournament_type::text,''))='SPIN') THEN
    v_start_authority:='spin_actual_start';
  ELSIF v_t.satellite_target_id IS NULL
     AND upper(COALESCE(v_t.tournament_type::text,''))='SNG'
     AND lower(COALESCE(v_t.variant::text,''))<>'spin'
     AND COALESCE(v_t.max_players,0)=2 THEN
    v_start_authority:='heads_up_sng_actual_start';
  END IF;
  /* A release performed by the launch that holds this event's INCOMPLETE
     launch receipt has its own start authority. The clock has passed
     start_time, but no hand has been dealt (checked below, fails closed)
     and the receipt has not been completed, so the seat-first proofs -
     started_at unset, launch not completed - are the right ones and the
     receipt records launch_release. The launch names its receipt through
     the transaction-local app.ca_launch_release_launch_id, set only by
     fn_ca_release_unseatable_registrant_at_launch. */
  IF v_start_authority='scheduled_clock' AND EXISTS (
       SELECT 1 FROM public.tournament_launch_receipts r
        WHERE r.tournament_id=p_tournament_id
          AND r.completed_at IS NULL
          AND r.launch_id::text=NULLIF(
            current_setting('app.ca_launch_release_launch_id',true),'')) THEN
    v_start_authority:='launch_release';
  END IF;

  -- A caller-supplied request id is a durable operation identity. It may only
  -- name this exact player/event/endpoint scope. If its pre-start outcome is
  -- already committed, replay that immutable outcome even when the wall clock
  -- is now past the start; this branch performs no new unregistration writes.
  IF p_request_id IS NOT NULL THEN
    IF EXISTS(
      SELECT 1 FROM public.tournament_unregistration_receipts r
       WHERE r.request_id=p_request_id
         AND (r.tournament_id IS DISTINCT FROM p_tournament_id
           OR r.user_id IS DISTINCT FROM p_user_id
           OR r.source_table_id IS DISTINCT FROM p_expected_table_id)) THEN
      RAISE EXCEPTION 'unregistration request id belongs to another intent'
        USING ERRCODE='22023';
    END IF;
    IF EXISTS(
      SELECT 1 FROM public.tournament_unregistration_receipts r
       WHERE r.request_id=p_request_id) THEN
      v_receipt:=public.fn_ca_tournament_unregistration_receipt(
        p_tournament_id,p_user_id,p_expected_table_id,p_request_id);
      IF v_receipt IS NOT NULL THEN
        RETURN v_receipt||jsonb_build_object('replayed',true);
      END IF;
      RAISE EXCEPTION
        'unregistration request id belongs to a prior registration lifecycle'
        USING ERRCODE='P0404';
    END IF;
  END IF;

  SELECT * INTO v_reg FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
     AND tp.status::text IN ('registered','playing')
   ORDER BY tp.id LIMIT 1 FOR UPDATE;
  IF upper(COALESCE(v_t.status::text,'')) NOT IN ('ANNOUNCED','REGISTERING') THEN
    RETURN jsonb_build_object('ok',false,'reason','registration_closed');
  END IF;

  -- A persisted hand is stronger actual-start evidence than either a mutable
  -- parent status or a launch receipt that an interrupted launcher failed to
  -- complete. Canonical accepted-hand commits carry tournament_id; the
  -- table-linked branch also fails closed for older rows that omitted it. The
  -- exclusive lifecycle advisory lock above serializes this read against the
  -- shared lock held by every canonical accepted-hand commit.
  SELECT EXISTS (
           SELECT 1
             FROM public.hand_history hh
            WHERE hh.tournament_id=p_tournament_id
         ) OR EXISTS (
           SELECT 1
             FROM public.tables hand_table
             JOIN public.hand_history hh ON hh.table_id=hand_table.id
            WHERE hand_table.tournament_id=p_tournament_id
         )
    INTO v_persisted_hand_exists;
  IF v_persisted_hand_exists THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_started');
  END IF;
  IF v_start_authority='scheduled_clock' THEN
    IF v_t.start_time IS NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','registration_schedule_unset');
    END IF;
    IF clock_timestamp()>=v_t.start_time THEN
      RETURN jsonb_build_object('ok',false,'reason','tournament_started');
    END IF;
  ELSE
    SELECT r.completed_at INTO v_launch_completed_at
      FROM public.tournament_launch_receipts r
     WHERE r.tournament_id=p_tournament_id;
    IF v_t.started_at IS NOT NULL OR v_launch_completed_at IS NOT NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','tournament_started');
    END IF;
  END IF;
  IF v_reg.id IS NULL THEN
    -- Rolling clients without a request id may recover a just-lost response
    -- only while registration remains open. They can never turn an old receipt
    -- into a successful post-start response.
    IF p_request_id IS NULL THEN
      v_receipt:=public.fn_ca_tournament_unregistration_receipt(
        p_tournament_id,p_user_id,p_expected_table_id,NULL);
      IF v_receipt IS NOT NULL THEN
        RETURN v_receipt||jsonb_build_object('replayed',true);
      END IF;
    END IF;
    RETURN jsonb_build_object('ok',false,'reason','not_registered');
  END IF;
  IF p_expected_table_id IS NOT NULL THEN
    SELECT s.seat_number INTO v_seat_number
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE s.table_id=p_expected_table_id AND s.user_id=p_user_id
       AND s.left_at IS NULL AND tb.tournament_id=p_tournament_id
     ORDER BY s.id LIMIT 1 FOR UPDATE OF s;
    IF v_seat_number IS NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','not_seated');
    END IF;
  END IF;
  IF EXISTS(
    SELECT 1 FROM public.spin_reserve_ledger r
     WHERE r.tournament_id=p_tournament_id
       AND r.kind IN ('contribution','jackpot_draw')) THEN
    RETURN jsonb_build_object('ok',false,'reason','spin_entry_already_booked');
  END IF;

  PERFORM 1 FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
   ORDER BY e.entitlement_kind,e.id FOR UPDATE;
  SELECT count(*) INTO v_non_cash_count
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
     AND e.registration_id=v_reg.id
     AND e.entitlement_kind IN ('satellite_seat','tournament_ticket')
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_tickets tk
        WHERE tk.source_refund_entitlement_id=e.id)
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_refund_tranches tr
        WHERE tr.entitlement_id=e.id);
  IF COALESCE(v_reg.is_satellite_qualifier,false)
     AND v_non_cash_count<>1 THEN
    RAISE EXCEPTION
      'satellite-funded registration % requires one unspent ticket entitlement',
      v_reg.id USING ERRCODE='P0404';
  END IF;
  IF NOT COALESCE(v_reg.is_satellite_qualifier,false)
     AND v_non_cash_count<>0 THEN
    RAISE EXCEPTION
      'cash registration % cannot own a satellite ticket entitlement',v_reg.id
      USING ERRCODE='P0404';
  END IF;

  SELECT round(COALESCE(sum(e.refund_prize),0),2),
         round(COALESCE(sum(e.refund_bounty),0),2),
         round(COALESCE(sum(e.refund_fee),0),2),
         round(COALESCE(sum(e.gross),0),2),
         round(COALESCE(sum(e.gross),0),2),
         0::numeric
    INTO v_refund_prize,v_refund_bounty,v_refund_fee,v_refund_total,
         v_wallet_amount,v_ticket_amount
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
     AND (e.entitlement_kind='wallet_charge' OR e.registration_id=v_reg.id)
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_refund_tranches tr
        WHERE tr.entitlement_id=e.id)
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_tickets tk
        WHERE tk.source_refund_entitlement_id=e.id);
  IF v_refund_total IS DISTINCT FROM
       round(v_refund_prize+v_refund_bounty+v_refund_fee,2)
     OR v_refund_total IS DISTINCT FROM
       round(v_wallet_amount+v_ticket_amount,2) THEN
    RAISE EXCEPTION 'registration % has invalid entitlement totals',v_reg.id
      USING ERRCODE='P0404';
  END IF;
  -- A funded satellite entry does not invent a player-wallet debit.
  -- It returns the same escrow value in cash through its exact source proof.
  IF COALESCE(v_reg.is_satellite_qualifier,false)
     AND EXISTS (
       SELECT 1 FROM public.tournament_refund_entitlements e
        WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
          AND e.entitlement_kind='wallet_charge'
          AND NOT EXISTS (
            SELECT 1 FROM public.tournament_refund_tranches tr
             WHERE tr.entitlement_id=e.id)) THEN
    RAISE EXCEPTION
      'satellite-funded registration % has an unexpected wallet charge',
      v_reg.id USING ERRCODE='P0404';
  END IF;

  SELECT round(COALESCE(sum(w.amount),0),2) INTO v_wallet_debits
    FROM public.wallet_transactions w
   WHERE w.related_entity_id=p_tournament_id AND w.user_id=p_user_id
     AND w.type='debit'
     AND lower(w.category) IN ('tournament_buyin','rebuy','addon');
  SELECT round(COALESCE(sum(e.gross),0),2) INTO v_entitled_wallet_total
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
     AND e.entitlement_kind='wallet_charge';
  SELECT round(COALESCE(sum(w.amount),0),2) INTO v_wallet_refunds_before
    FROM public.wallet_transactions w
   WHERE w.related_entity_id=p_tournament_id AND w.user_id=p_user_id
     AND w.type='credit'
     AND lower(w.category) IN ('refund','tournament_refund');
  SELECT round(COALESCE(sum(tr.amount_paid_now),0),2) INTO v_tranche_total
    FROM public.tournament_refund_tranches tr
   WHERE tr.tournament_id=p_tournament_id AND tr.user_id=p_user_id;
  IF v_wallet_debits IS DISTINCT FROM v_entitled_wallet_total
     OR v_wallet_refunds_before IS DISTINCT FROM v_tranche_total
     OR v_wallet_refunds_before>(
       SELECT COALESCE(sum(e.gross),0)
         FROM public.tournament_refund_entitlements e
        WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
          AND NOT EXISTS (
            SELECT 1 FROM public.tournament_tickets tk
             WHERE tk.source_refund_entitlement_id=e.id)) THEN
    RAISE EXCEPTION 'registration % wallet and entitlement journals disagree',v_reg.id
      USING ERRCODE='P0404';
  END IF;
  v_running_owed:=v_tranche_total;

  SELECT round(COALESCE(sum(r.rake_amount),0),2) INTO v_rake_before
    FROM public.rake_records r
   WHERE r.tournament_id=p_tournament_id AND r.is_tournament;
  SELECT COALESCE(array_agg(e.id ORDER BY e.id),ARRAY[]::uuid[])
    INTO v_fee_entitlement_ids
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
     AND (e.entitlement_kind='wallet_charge' OR e.registration_id=v_reg.id)
     AND e.refund_fee>0
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_refund_tranches tr
        WHERE tr.entitlement_id=e.id)
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_tickets tk
        WHERE tk.source_refund_entitlement_id=e.id);

  -- Bind every fee-bearing entitlement to its actual same-transaction rake
  -- journal. The refund wallet club is deliberately absent from this match:
  -- it identifies the payer, while rake_records.club_id identifies the fee
  -- recipient and can be a different club.
  WITH fee_sources AS MATERIALIZED (
    SELECT e.id AS entitlement_id,r.id AS rake_record_id,
           r.club_id,r.rake_amount
      FROM public.tournament_refund_entitlements e
      JOIN public.chip_ledger l ON l.id=e.source_ledger_id
      JOIN public.rake_records r
        ON r.tournament_id=e.tournament_id
       AND r.is_tournament IS TRUE
       AND r.club_id IS NOT NULL
       AND r.rake_amount=e.refund_fee
       AND r.created_at=l.created_at
       AND r.metadata->>'user_id'=e.user_id::text
       AND (
         (e.entitlement_kind='wallet_charge'
          AND e.charge_category='tournament_buyin'
          AND r.source IN (
            'fn_register_for_tournament','fn_register_horse_for_tournament')
          AND r.metadata->>'kind'='tournament_entry_fee'
          AND r.metadata->>'registration_id'=v_reg.id::text)
         OR (e.entitlement_kind='wallet_charge'
          AND e.charge_category='rebuy'
          AND r.source='process_tournament_rebuy'
          AND r.metadata->>'kind' IN (
            'tournament_rebuy_fee','tournament_reentry_fee'))
         OR (e.entitlement_kind='satellite_seat'
          AND r.source='fn_award_satellite_seat'
          AND r.metadata->>'kind'='satellite_seat_entry_fee'
          AND r.metadata->>'registration_id'=e.registration_id::text)
         OR (e.entitlement_kind='tournament_ticket'
          AND r.source='fn_register_for_tournament_with_ticket'
          AND r.metadata->>'kind'='tournament_ticket_entry_fee'
          AND r.metadata->>'registration_id'=e.registration_id::text))
     WHERE e.id=ANY(v_fee_entitlement_ids)
  )
  SELECT count(*),count(DISTINCT entitlement_id),
         round(COALESCE(sum(rake_amount),0),2),
         COALESCE(array_agg(rake_record_id ORDER BY rake_record_id),
                  ARRAY[]::uuid[])
    INTO v_fee_source_count,v_fee_source_entitlement_count,
         v_fee_source_amount,v_fee_source_rake_record_ids
    FROM fee_sources;
  IF v_fee_source_count<>cardinality(v_fee_entitlement_ids)
     OR v_fee_source_entitlement_count<>cardinality(v_fee_entitlement_ids)
     OR v_fee_source_count<>(
       SELECT count(DISTINCT id)
         FROM unnest(v_fee_source_rake_record_ids) source(id))
     OR v_fee_source_amount IS DISTINCT FROM v_refund_fee THEN
    RAISE EXCEPTION
      'registration % fee entitlements do not map one-to-one to exact rake evidence',
      v_reg.id USING ERRCODE='P0404';
  END IF;
  PERFORM 1 FROM public.rake_records r
   WHERE r.id=ANY(v_fee_source_rake_record_ids)
   ORDER BY r.club_id,r.id FOR UPDATE;

  PERFORM public.fn_ca_escrow_apply(
    p_tournament_id,'unregister entitlement escrow prelock');
  SELECT * INTO v_escrow_before FROM public.tournament_escrow e
   WHERE e.tournament_id=p_tournament_id FOR UPDATE;
  SELECT count(*) INTO v_players_before FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND tp.status::text IN ('registered','playing');
  IF v_escrow_before.tournament_id IS NULL
     OR v_escrow_before.enforced IS DISTINCT FROM true
     OR v_players_before<=0
     OR v_t.current_players IS DISTINCT FROM v_players_before
     OR v_t.prize_pool IS DISTINCT FROM v_escrow_before.prize_balance
     OR v_t.bounty_pool IS DISTINCT FROM v_escrow_before.bounty_balance
     OR v_t.total_rake IS DISTINCT FROM v_escrow_before.fee_balance
     OR v_t.total_rake IS DISTINCT FROM v_rake_before
     OR v_t.prize_pool<v_refund_prize
     OR v_t.bounty_pool<v_refund_bounty
     OR v_t.total_rake<v_refund_fee THEN
    RAISE EXCEPTION 'registration % cannot leave divergent tournament state',v_reg.id
      USING ERRCODE='P0404';
  END IF;

  FOR v_ent IN
    SELECT e.* FROM public.tournament_refund_entitlements e
     WHERE e.tournament_id=p_tournament_id AND e.user_id=p_user_id
       AND (e.entitlement_kind='wallet_charge' OR e.registration_id=v_reg.id)
       AND NOT EXISTS(
         SELECT 1 FROM public.tournament_refund_tranches tr
          WHERE tr.entitlement_id=e.id)
       AND NOT EXISTS(
         SELECT 1 FROM public.tournament_tickets tk
          WHERE tk.source_refund_entitlement_id=e.id)
     ORDER BY e.entitlement_kind,e.id
  LOOP
    v_running_owed:=round(v_running_owed+v_ent.gross,2);
    v_settle:=public.fn_settle_tournament_refund_exact(
      p_tournament_id,p_user_id,v_ent.refund_wallet_club_id,v_running_owed,
      v_ent.refund_prize,v_ent.refund_bounty,v_ent.refund_fee,
      'fn_unregister_from_tournament',v_description);
    IF COALESCE((v_settle->>'ok')::boolean,false) IS NOT TRUE
       OR (v_settle->>'entitlement_id')::uuid IS DISTINCT FROM v_ent.id
       OR (v_settle->>'paid')::numeric IS DISTINCT FROM v_ent.gross
       OR (v_settle->>'amount_paid')::numeric IS DISTINCT FROM v_running_owed
       OR (v_settle->>'source_wallet_club_id')::uuid
            IS DISTINCT FROM v_ent.refund_wallet_club_id THEN
      RAISE EXCEPTION 'registration % exact wallet refund failed',v_reg.id
        USING ERRCODE='P0404';
    END IF;
    v_entitlement_ids:=array_append(v_entitlement_ids,v_ent.id);
    v_source_wallet_club_ids:=array_append(
      v_source_wallet_club_ids,v_ent.refund_wallet_club_id);
    v_credit_ledger_ids:=array_append(
      v_credit_ledger_ids,(v_settle->>'credit_ledger_id')::uuid);
    v_wallet_transaction_ids:=array_append(
      v_wallet_transaction_ids,(v_settle->>'wallet_transaction_id')::uuid);
  END LOOP;

  FOR v_fee_group IN
    SELECT r.club_id,round(sum(r.rake_amount),2) AS fee,
           array_agg(r.id ORDER BY r.id) AS source_rake_record_ids,
           array_agg(e.id ORDER BY e.id) AS entitlement_ids
      FROM public.rake_records r
      JOIN public.tournament_refund_entitlements e
        ON e.id=ANY(v_fee_entitlement_ids)
       AND e.refund_fee=r.rake_amount
       AND e.tournament_id=r.tournament_id
       AND e.user_id=p_user_id
       AND r.metadata->>'user_id'=e.user_id::text
       AND (
         (e.entitlement_kind='wallet_charge'
          AND e.charge_category='tournament_buyin'
          AND r.source IN (
            'fn_register_for_tournament','fn_register_horse_for_tournament')
          AND r.metadata->>'kind'='tournament_entry_fee'
          AND r.metadata->>'registration_id'=v_reg.id::text)
         OR (e.entitlement_kind='wallet_charge'
          AND e.charge_category='rebuy'
          AND r.source='process_tournament_rebuy'
          AND r.metadata->>'kind' IN (
            'tournament_rebuy_fee','tournament_reentry_fee'))
         OR (e.entitlement_kind='satellite_seat'
          AND r.source='fn_award_satellite_seat'
          AND r.metadata->>'kind'='satellite_seat_entry_fee'
          AND r.metadata->>'registration_id'=e.registration_id::text)
         OR (e.entitlement_kind='tournament_ticket'
          AND r.source='fn_register_for_tournament_with_ticket'
          AND r.metadata->>'kind'='tournament_ticket_entry_fee'
          AND r.metadata->>'registration_id'=e.registration_id::text))
      JOIN public.chip_ledger l
        ON l.id=e.source_ledger_id AND l.created_at=r.created_at
     WHERE r.id=ANY(v_fee_source_rake_record_ids)
     GROUP BY r.club_id ORDER BY r.club_id
  LOOP
    IF v_fee_group.fee>0 THEN
      INSERT INTO public.rake_records(
        hand_id,table_id,club_id,rake_amount,pot_size,num_players,
        bbj_contribution,is_tournament,tournament_id,source,metadata)
      VALUES(
        NULL,NULL,v_fee_group.club_id,-v_fee_group.fee,v_fee_group.fee,1,
        0,true,p_tournament_id,'fn_unregister_from_tournament',
        jsonb_build_object(
          'kind','tournament_fee_refund','user_id',p_user_id,
          'registration_id',v_reg.id,
          'fee_recipient_club_id',v_fee_group.club_id,
          'entitlement_ids',to_jsonb(v_fee_group.entitlement_ids),
          'original_rake_record_ids',
            to_jsonb(v_fee_group.source_rake_record_ids)))
      RETURNING id INTO v_fee_reversal_id;
      v_fee_reversal_ids:=array_append(
        v_fee_reversal_ids,v_fee_reversal_id);
      v_fees_reversed:=round(v_fees_reversed+v_fee_group.fee,2);
    END IF;
  END LOOP;
  SELECT COALESCE(array_agg(id ORDER BY id),ARRAY[]::uuid[])
    INTO v_fee_reversal_ids
    FROM unnest(v_fee_reversal_ids) reversal(id);
  IF v_fees_reversed IS DISTINCT FROM v_refund_fee THEN
    RAISE EXCEPTION
      'registration % reversed % in exact fee rows but owes %',
      v_reg.id,v_fees_reversed,v_refund_fee USING ERRCODE='P0404';
  END IF;

  UPDATE public.tournaments
     SET current_players=v_players_before-1,
         prize_pool=round(v_t.prize_pool-v_refund_prize,2),
         bounty_pool=round(v_t.bounty_pool-v_refund_bounty,2),
         total_rake=round(v_t.total_rake-v_refund_fee,2),updated_at=now()
   WHERE id=p_tournament_id
     AND current_players IS NOT DISTINCT FROM v_players_before
     AND prize_pool IS NOT DISTINCT FROM v_t.prize_pool
     AND bounty_pool IS NOT DISTINCT FROM v_t.bounty_pool
     AND total_rake IS NOT DISTINCT FROM v_t.total_rake;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'registration % tournament cache changed',v_reg.id
      USING ERRCODE='40001';
  END IF;

  UPDATE public.table_seats s
     SET left_at=transaction_timestamp(),status='left',leave_pending=false,
         is_sitting_out=false,is_away=false,sit_out_at=NULL,
         scheduled_leave_hands=NULL
   WHERE s.user_id=p_user_id AND s.left_at IS NULL
     AND EXISTS(SELECT 1 FROM public.tables tb
                 WHERE tb.id=s.table_id AND tb.tournament_id=p_tournament_id);
  UPDATE public.tables tb
     SET current_players=(SELECT count(*) FROM public.table_seats s
                           WHERE s.table_id=tb.id AND s.left_at IS NULL),
         updated_at=now()
   WHERE tb.tournament_id=p_tournament_id;
  DELETE FROM public.tournament_players tp WHERE tp.id=v_reg.id;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'registration % was not deleted after settlement',v_reg.id
      USING ERRCODE='40001';
  END IF;

  SELECT * INTO v_escrow_after FROM public.tournament_escrow e
   WHERE e.tournament_id=p_tournament_id;
  SELECT round(COALESCE(sum(r.rake_amount),0),2) INTO v_rake_after
    FROM public.rake_records r
   WHERE r.tournament_id=p_tournament_id AND r.is_tournament;
  SELECT round(COALESCE(sum(w.amount),0),2) INTO v_wallet_refunds_after
    FROM public.wallet_transactions w
   WHERE w.related_entity_id=p_tournament_id AND w.user_id=p_user_id
     AND w.type='credit'
     AND lower(w.category) IN ('refund','tournament_refund');
  IF (SELECT count(*) FROM public.tournament_players tp
       WHERE tp.tournament_id=p_tournament_id
         AND tp.status::text IN ('registered','playing'))<>v_players_before-1
     OR v_wallet_refunds_after IS DISTINCT FROM
          round(v_wallet_refunds_before+v_wallet_amount,2)
     OR v_escrow_after.prize_balance IS DISTINCT FROM
          round(v_escrow_before.prize_balance-v_refund_prize,2)
     OR v_escrow_after.bounty_balance IS DISTINCT FROM
          round(v_escrow_before.bounty_balance-v_refund_bounty,2)
     OR v_escrow_after.fee_balance IS DISTINCT FROM
          round(v_escrow_before.fee_balance-v_refund_fee,2)
     OR v_rake_after IS DISTINCT FROM round(v_rake_before-v_refund_fee,2)
     OR NOT EXISTS(
       SELECT 1 FROM public.tournaments t
        WHERE t.id=p_tournament_id
          AND t.current_players=v_players_before-1
          AND t.prize_pool=v_escrow_after.prize_balance
          AND t.bounty_pool=v_escrow_after.bounty_balance
          AND t.total_rake=v_rake_after) THEN
    RAISE EXCEPTION 'registration % did not leave exact final state',v_reg.id
      USING ERRCODE='P0404';
  END IF;
  IF p_expected_table_id IS NOT NULL THEN
    SELECT count(*) INTO v_seats_taken FROM public.table_seats s
     WHERE s.table_id=p_expected_table_id AND s.left_at IS NULL;
  END IF;

  -- Re-prove the chosen start authority after all money and seat work. Timed
  -- events still use the locked schedule cutoff; every product also treats a
  -- persisted hand as irreversible start truth; seat-first products further
  -- use status, started_at and completed launch truth. Any loss of the race
  -- rolls every preceding write back atomically.
  v_unregistered_at:=clock_timestamp();
  SELECT EXISTS (
           SELECT 1
             FROM public.hand_history hh
            WHERE hh.tournament_id=p_tournament_id
         ) OR EXISTS (
           SELECT 1
             FROM public.tables hand_table
             JOIN public.hand_history hh ON hh.table_id=hand_table.id
            WHERE hand_table.tournament_id=p_tournament_id
         )
    INTO v_persisted_hand_exists;
  IF v_persisted_hand_exists THEN
    RAISE EXCEPTION
      'tournament hand persisted before unregistration could commit'
      USING ERRCODE='55000';
  END IF;
  IF v_start_authority='scheduled_clock' THEN
    IF v_unregistered_at>=v_t.start_time THEN
      RAISE EXCEPTION 'tournament started before unregistration could commit'
        USING ERRCODE='55000';
    END IF;
  ELSE
    SELECT t.status::text,t.started_at,launch.completed_at
      INTO v_actual_status,v_actual_started_at,v_launch_completed_at
      FROM public.tournaments t
      LEFT JOIN public.tournament_launch_receipts launch
        ON launch.tournament_id=t.id
     WHERE t.id=p_tournament_id;
    IF upper(COALESCE(v_actual_status,'')) NOT IN ('ANNOUNCED','REGISTERING')
       OR v_actual_started_at IS NOT NULL
       OR v_launch_completed_at IS NOT NULL THEN
      RAISE EXCEPTION
        'seat-first tournament started before unregistration could commit'
        USING ERRCODE='55000';
    END IF;
  END IF;

  INSERT INTO public.tournament_unregistration_receipts(
    registration_id,request_id,tournament_id,user_id,source_table_id,
    refunded_chips,returned_ticket_value,entitlement_ids,ticket_ids,
    source_wallet_club_ids,credit_ledger_ids,wallet_transaction_ids,
    fees_reversed,fee_reversal_ids,fee_source_rake_record_ids,
    seat_number,seats_taken,scheduled_start_at,start_authority,settled_at)
  VALUES(
    v_reg.id,v_request_id,p_tournament_id,p_user_id,p_expected_table_id,
    v_wallet_amount,v_ticket_amount,v_entitlement_ids,v_ticket_ids,
    v_source_wallet_club_ids,v_credit_ledger_ids,v_wallet_transaction_ids,
    v_fees_reversed,v_fee_reversal_ids,v_fee_source_rake_record_ids,
    v_seat_number,v_seats_taken,v_t.start_time,v_start_authority,v_unregistered_at);
  v_receipt:=public.fn_ca_tournament_unregistration_receipt(
    p_tournament_id,p_user_id,p_expected_table_id,v_request_id);
  IF v_receipt IS NULL
     OR (v_receipt->>'registration_id')::uuid IS DISTINCT FROM v_reg.id THEN
    RAISE EXCEPTION 'registration % has no exact unregistration receipt',v_reg.id
      USING ERRCODE='P0404';
  END IF;
  RETURN v_receipt||jsonb_build_object('replayed',false);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_create_seat_first_game_atomic(p_tournament_id uuid, p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_existing public.tournaments%ROWTYPE;
  v_existing_table public.tables%ROWTYPE;
  v_existing_table_count integer;
  v_created public.tournaments%ROWTYPE;
  v_table_id uuid;
  v_club_id uuid;
  v_union_id uuid;
  v_name text;
  v_game_type text;
  v_table_variant text;
  v_variant text;
  v_tournament_type text;
  v_buy_in numeric;
  v_buy_in_fee numeric;
  v_guarantee numeric;
  v_starting_chips integer;
  v_max_players integer;
  v_min_players integer;
  v_table_size integer;
  v_blinds jsonb;
  v_payouts jsonb;
  v_start_time timestamptz;
  v_late_reg_levels integer;
  v_late_reg_mins integer;
  v_satellite_target_id uuid;
  v_satellite_seats integer;
  v_short_description text;
  v_requested_current_players integer;
  v_requested_status text;
  v_first_level jsonb;
  v_small_blind numeric;
  v_big_blind numeric;
BEGIN
  IF p_tournament_id IS NULL OR p_config IS NULL OR jsonb_typeof(p_config) <> 'object' THEN
    RAISE EXCEPTION 'SEAT_FIRST_CREATE_INVALID_REQUEST'
      USING ERRCODE = '22023';
  END IF;

  /* Every accepted request key must be represented by the durable pair below.
     Rejecting unknown keys prevents an idempotent replay from appearing exact
     after a caller adds configuration this creator silently ignores. */
  IF EXISTS (
    SELECT 1
      FROM jsonb_object_keys(p_config) AS supplied(key)
     WHERE supplied.key NOT IN (
       'club_id', 'union_id', 'name', 'game_type', 'variant',
       'tournament_type', 'buy_in_amount', 'buy_in_fee', 'guaranteed_prize',
       'starting_chips', 'max_players', 'min_players', 'table_size',
       'current_players', 'status', 'blind_structure', 'payout_structure',
       'start_time', 'late_reg_levels', 'late_reg_mins',
       'satellite_target_id', 'satellite_seats', 'short_description',
       'spin_multiplier', 'spin_locked_tiers'
     )
  ) THEN
    RAISE EXCEPTION 'SEAT_FIRST_CREATE_UNKNOWN_CONFIG_KEY'
      USING ERRCODE = '22023';
  END IF;

  /* This is an entry-producing transaction. It takes the same first lock as
     every purchase path, before the idempotency key or either game row. */
  PERFORM pg_advisory_xact_lock_shared(530090, 1);
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'platform_frozen');
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:seat-first-create:' || p_tournament_id::text, 0)
  );

  v_club_id := NULLIF(p_config->>'club_id', '')::uuid;
  v_union_id := NULLIF(p_config->>'union_id', '')::uuid;
  v_name := NULLIF(btrim(p_config->>'name'), '');
  v_game_type := NULLIF(btrim(p_config->>'game_type'), '');
  v_table_variant := lower(v_game_type);
  v_variant := lower(NULLIF(btrim(p_config->>'variant'), ''));
  v_tournament_type := upper(NULLIF(btrim(p_config->>'tournament_type'), ''));
  v_buy_in := COALESCE(NULLIF(p_config->>'buy_in_amount', '')::numeric, 0);
  v_buy_in_fee := COALESCE(NULLIF(p_config->>'buy_in_fee', '')::numeric, 0);
  v_guarantee := COALESCE(NULLIF(p_config->>'guaranteed_prize', '')::numeric, 0);
  v_starting_chips := NULLIF(p_config->>'starting_chips', '')::integer;
  v_max_players := NULLIF(p_config->>'max_players', '')::integer;
  v_min_players := COALESCE(NULLIF(p_config->>'min_players', '')::integer, v_max_players);
  v_table_size := COALESCE(NULLIF(p_config->>'table_size', '')::integer, v_max_players);
  v_blinds := p_config->'blind_structure';
  v_payouts := COALESCE(p_config->'payout_structure', '[]'::jsonb);
  v_start_time := NULLIF(p_config->>'start_time', '')::timestamptz;
  v_late_reg_levels := COALESCE(NULLIF(p_config->>'late_reg_levels', '')::integer, 0);
  v_late_reg_mins := COALESCE(NULLIF(p_config->>'late_reg_mins', '')::integer, 0);
  v_satellite_target_id := NULLIF(p_config->>'satellite_target_id', '')::uuid;
  v_satellite_seats := NULLIF(p_config->>'satellite_seats', '')::integer;
  v_short_description := NULLIF(btrim(p_config->>'short_description'), '');
  v_requested_current_players :=
    COALESCE(NULLIF(p_config->>'current_players', '')::integer, 0);
  v_requested_status :=
    upper(COALESCE(NULLIF(btrim(p_config->>'status'), ''), 'REGISTERING'));

  IF v_club_id IS NULL
     OR v_name IS NULL
     OR v_game_type IS NULL
     OR v_variant IS NULL
     OR v_tournament_type IS NULL
     OR v_starting_chips IS NULL OR v_starting_chips <= 0
     OR v_max_players IS NULL OR v_max_players < 2 OR v_max_players > 3
     OR v_min_players < 2 OR v_min_players > v_max_players
     OR v_table_size <> v_max_players
     OR v_start_time IS NULL
     OR jsonb_typeof(v_blinds) <> 'array'
     OR jsonb_array_length(v_blinds) = 0
     OR jsonb_typeof(v_payouts) <> 'array'
     OR NOT (v_variant = 'spin' OR v_max_players = 2)
     OR v_tournament_type NOT IN ('SPIN', 'SNG', 'SATELLITE')
     OR v_table_variant NOT IN ('nlh', 'plo4', 'plo5', 'plo6', 'plo8', 'short_deck', 'flh', 'flo8')
     OR v_requested_current_players <> 0
     OR v_requested_status <> 'REGISTERING'
     OR NULLIF(p_config->>'spin_multiplier', '') IS NOT NULL
     OR (
       p_config ? 'spin_locked_tiers'
       AND jsonb_typeof(p_config->'spin_locked_tiers') IS DISTINCT FROM 'null'
     )
     OR (v_tournament_type = 'SPIN' AND (v_variant <> 'spin' OR v_max_players <> 3))
     OR (
       v_tournament_type = 'SATELLITE'
       AND (
         v_satellite_target_id IS NULL
         OR v_satellite_seats IS NULL
         OR v_satellite_seats <= 0
         OR v_satellite_seats > v_max_players
       )
     )
     OR (
       v_tournament_type <> 'SATELLITE'
       AND (v_satellite_target_id IS NOT NULL OR v_satellite_seats IS NOT NULL)
     )
     OR v_buy_in < 0 OR v_buy_in_fee < 0 OR v_guarantee < 0 THEN
    RAISE EXCEPTION 'SEAT_FIRST_CREATE_INVALID_CONFIG'
      USING ERRCODE = '22023';
  END IF;

  v_first_level := v_blinds->0;
  v_small_blind := COALESCE(
    NULLIF(v_first_level->>'smallBlind', '')::numeric,
    NULLIF(v_first_level->>'small_blind', '')::numeric,
    NULLIF(v_first_level->>'sb', '')::numeric
  );
  v_big_blind := COALESCE(
    NULLIF(v_first_level->>'bigBlind', '')::numeric,
    NULLIF(v_first_level->>'big_blind', '')::numeric,
    NULLIF(v_first_level->>'bb', '')::numeric
  );
  IF v_small_blind IS NULL OR v_small_blind <= 0
     OR v_big_blind IS NULL OR v_big_blind < v_small_blind THEN
    RAISE EXCEPTION 'SEAT_FIRST_CREATE_INVALID_BLINDS'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_existing
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF FOUND THEN
    SELECT count(*) INTO v_existing_table_count
      FROM public.tables tb
     WHERE tb.tournament_id = p_tournament_id
       AND COALESCE(tb.is_deleted, false) = false
       AND tb.status IN ('waiting', 'running');

    IF v_existing_table_count <> 1 THEN
      RAISE EXCEPTION
        'SEAT_FIRST_ATOMIC_PARTIAL_STATE: tournament % has % joinable tables',
        p_tournament_id, v_existing_table_count
        USING ERRCODE = '23514';
    END IF;

    SELECT tb.* INTO v_existing_table
      FROM public.tables tb
     WHERE tb.tournament_id = p_tournament_id
       AND COALESCE(tb.is_deleted, false) = false
       AND tb.status IN ('waiting', 'running')
     ORDER BY tb.created_at, tb.id
     LIMIT 1
     FOR UPDATE;
    v_table_id := v_existing_table.id;

    IF v_existing.club_id IS DISTINCT FROM v_club_id
       OR v_existing.union_id IS DISTINCT FROM v_union_id
       OR v_existing.name IS DISTINCT FROM v_name
       OR lower(v_existing.game_type) IS DISTINCT FROM lower(v_game_type)
       OR lower(v_existing.variant) IS DISTINCT FROM v_variant
       OR upper(v_existing.tournament_type) IS DISTINCT FROM v_tournament_type
       OR v_existing.buy_in_amount IS DISTINCT FROM v_buy_in
       OR v_existing.buy_in_fee IS DISTINCT FROM v_buy_in_fee
       OR v_existing.guaranteed_prize IS DISTINCT FROM v_guarantee
       OR v_existing.starting_chips IS DISTINCT FROM v_starting_chips
       OR v_existing.max_players IS DISTINCT FROM v_max_players
       OR v_existing.min_players IS DISTINCT FROM v_min_players
       OR v_existing.table_size IS DISTINCT FROM v_table_size
       OR (v_existing.blind_structure)::jsonb IS DISTINCT FROM v_blinds
       OR (v_existing.payout_structure)::jsonb IS DISTINCT FROM v_payouts
       OR v_existing.start_time IS DISTINCT FROM v_start_time
       OR v_existing.late_reg_levels IS DISTINCT FROM v_late_reg_levels
       OR v_existing.late_reg_mins IS DISTINCT FROM v_late_reg_mins
       OR v_existing.satellite_target_id IS DISTINCT FROM v_satellite_target_id
       OR v_existing.satellite_seats IS DISTINCT FROM v_satellite_seats
       OR v_existing.short_description IS DISTINCT FROM v_short_description
       OR v_existing_table.club_id IS DISTINCT FROM v_club_id
       OR v_existing_table.tournament_id IS DISTINCT FROM p_tournament_id
       OR v_existing_table.name IS DISTINCT FROM v_name
       OR lower(v_existing_table.game_type) IS DISTINCT FROM 'tournament'
       OR lower(v_existing_table.game_variant) IS DISTINCT FROM v_table_variant
       OR v_existing_table.stakes IS DISTINCT FROM
          (v_small_blind::text || '/' || v_big_blind::text)
       OR v_existing_table.small_blind IS DISTINCT FROM v_small_blind
       OR v_existing_table.big_blind IS DISTINCT FROM v_big_blind
       OR v_existing_table.min_buy_in IS DISTINCT FROM 0::numeric
       OR v_existing_table.max_buy_in IS DISTINCT FROM 0::numeric
       OR v_existing_table.max_players IS DISTINCT FROM v_max_players THEN
      RAISE EXCEPTION 'SEAT_FIRST_CREATE_IDEMPOTENCY_MISMATCH: %', p_tournament_id
        USING ERRCODE = '22023';
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'replayed', true,
      'tournament', to_jsonb(v_existing),
      'table_id', v_table_id
    );
  END IF;

  INSERT INTO public.tournaments (
    id, club_id, union_id, name, game_type, variant, tournament_type,
    buy_in_amount, buy_in_fee, guaranteed_prize, starting_chips,
    max_players, min_players, table_size, current_players, status,
    blind_structure, payout_structure, start_time,
    late_reg_levels, late_reg_mins,
    satellite_target_id, satellite_seats, short_description
  ) VALUES (
    p_tournament_id, v_club_id, v_union_id, v_name, v_game_type, v_variant,
    v_tournament_type, v_buy_in, v_buy_in_fee, v_guarantee, v_starting_chips,
    v_max_players, v_min_players, v_table_size, 0, 'REGISTERING',
    v_blinds::text, v_payouts::text, v_start_time,
    v_late_reg_levels, v_late_reg_mins,
    v_satellite_target_id, v_satellite_seats, v_short_description
  ) RETURNING * INTO v_created;

  INSERT INTO public.tables (
    club_id, tournament_id, name, game_type, game_variant, stakes,
    small_blind, big_blind, min_buy_in, max_buy_in,
    max_players, current_players, status
  ) VALUES (
    v_club_id, p_tournament_id, v_name, 'tournament', v_table_variant,
    v_small_blind::text || '/' || v_big_blind::text,
    v_small_blind, v_big_blind, 0, 0,
    v_max_players, 0, 'waiting'
  ) RETURNING id INTO v_table_id;

  RETURN jsonb_build_object(
    'ok', true,
    'replayed', false,
    'tournament', to_jsonb(v_created),
    'table_id', v_table_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_create_tournament_governed_legacy(p_club_id uuid, p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid          uuid := auth.uid();
  v_id           uuid;
  v_total        numeric;
  v_buy_in       numeric;
  v_fee          numeric;
  v_max_players  int;
  v_min_players  int;
  v_type         text;
  v_variant      text;
  v_start        timestamptz;
  v_payouts      jsonb;
  v_blinds       jsonb;
  v_pct_total    numeric;
  v_is_bounty    boolean;
  v_bounty       numeric;
  v_union_id     uuid;
  v_is_private   boolean;
  v_action_time    int;
  v_table_size     int;
  v_addon_break    int;
  v_early_chips    int;
  v_restart_every  int;
  v_sync_breaks    boolean;
  v_max_rebuys     int;
  v_max_reentries  int;
  v_is_multi_day   boolean;
  v_total_days     int;
  v_mb_min_mult    numeric;
  v_mb_max_mult    numeric;
  v_mb_min_money   numeric := 0;
  v_mb_max_money   numeric := 0;
  v_sat_target     uuid;
  v_sat_seats      int;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;

  v_is_private := COALESCE((p_config->>'isPrivate')::boolean, false);
  IF v_is_private THEN
    IF NOT (is_club_admin(p_club_id, v_uid) OR public.fn_can_create_games(p_club_id, v_uid)) THEN
      RETURN jsonb_build_object('success', false, 'error', 'not_authorised');
    END IF;
  ELSIF NOT public.fn_can_create_games(p_club_id, v_uid) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorised');
  END IF;

  -- Keep the database launch boundary aligned with the tournament catalogue.
  -- Authentication and club authority above remain the existing first gates.
  IF p_config IS NOT NULL AND jsonb_typeof(p_config) <> 'object' THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_configuration');
  END IF;
  p_config := jsonb_set(COALESCE(p_config, '{}'::jsonb), '{gameVariant}',
    to_jsonb(upper(btrim(COALESCE(p_config->>'gameVariant', 'NLH')))), true);
  IF p_config->>'gameVariant' NOT IN ('NLH','PLO4','PLO5','PLO6','PLO8','SHORT_DECK','FLH','FLO8') THEN
    RETURN jsonb_build_object('success', false, 'error', 'unsupported_tournament_variant');
  END IF;

  IF lower(COALESCE(p_config->>'type','mtt'))='spin'
     AND p_config->>'gameVariant' NOT IN ('NLH','PLO4','PLO5','PLO6') THEN
    RETURN jsonb_build_object('success', false, 'error', 'unsupported_spin_variant');
  END IF;

  v_total := COALESCE((p_config->>'buyIn')::numeric, 0);
  IF v_total < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'buy_in_must_not_be_negative');
  END IF;
  IF v_total <> round(v_total) THEN
    RETURN jsonb_build_object('success', false, 'error', 'buy_in_must_be_whole');
  END IF;

  v_fee    := LEAST(v_total, GREATEST(0, trunc(v_total * (CASE WHEN COALESCE((p_config->>'maxPlayers')::int, 0) BETWEEN 1 AND 2 THEN 0.05 ELSE 0.1 END) * 100 + 0.000001) / 100));
  v_buy_in := v_total - v_fee;

  v_max_players := COALESCE((p_config->>'maxPlayers')::int, 0);
  IF v_max_players <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'max_players_must_be_positive');
  END IF;
  v_min_players := GREATEST(COALESCE((p_config->>'minPlayers')::int, 3), 2);
  IF v_min_players > v_max_players THEN
    v_min_players := v_max_players;
  END IF;

  v_type := COALESCE(p_config->>'type', 'mtt');
  v_variant := CASE v_type
                 WHEN 'sng' THEN 'sng'
                 WHEN 'spin' THEN 'spin'
                 WHEN 'bounty' THEN 'bounty'
                 WHEN 'progressive_bounty' THEN 'progressive_bounty'
                 WHEN 'mystery_bounty' THEN 'mystery_bounty'
                 WHEN 'satellite' THEN 'satellite'
                 ELSE 'freezeout'
               END;

  IF v_type = 'spin' THEN
    v_fee    := 0;
    v_buy_in := v_total;
  END IF;

  v_blinds  := COALESCE(p_config->'blindStructure', '[]'::jsonb);
  v_payouts := COALESCE(p_config->'payoutStructure', '[]'::jsonb);

  IF jsonb_array_length(v_blinds) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'blind_structure_required');
  END IF;
  IF jsonb_array_length(v_payouts) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'payout_structure_required');
  END IF;

  SELECT COALESCE(SUM((e->>'percentage')::numeric), 0) INTO v_pct_total
    FROM jsonb_array_elements(v_payouts) e;
  IF abs(v_pct_total - 100) > 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'payouts_must_total_100',
                              'detail', v_pct_total);
  END IF;

  IF jsonb_array_length(v_payouts) > v_max_players THEN
    RETURN jsonb_build_object('success', false, 'error', 'more_paid_places_than_players');
  END IF;

  v_start := COALESCE((p_config->>'startTime')::timestamptz, now() + interval '1 minute');

  v_is_bounty := v_type IN ('bounty', 'progressive_bounty', 'mystery_bounty');
  v_bounty := COALESCE((p_config->>'bountyAmount')::numeric, 0);
  IF v_is_bounty THEN
    IF v_bounty <= 0 THEN
      RETURN jsonb_build_object('success', false, 'error', 'bounty_amount_required');
    END IF;
    IF v_bounty <> round(v_bounty) THEN
      RETURN jsonb_build_object('success', false, 'error', 'bounty_must_be_whole');
    END IF;
    IF v_buy_in - v_bounty < 0 THEN
      RETURN jsonb_build_object('success', false, 'error', 'bounty_exceeds_buy_in');
    END IF;
  END IF;

  v_action_time := LEAST(60, GREATEST(5,  COALESCE((p_config->>'actionTimeSeconds')::int, 15)));
  v_table_size  := LEAST(10, GREATEST(2,  COALESCE((p_config->>'tableSize')::int, 9)));
  v_addon_break := LEAST(10, GREATEST(1,  COALESCE((p_config->>'addonBreakMinutes')::int, 1)));
  v_sync_breaks := COALESCE((p_config->>'synchronizedBreaks')::boolean, true);

  v_early_chips := COALESCE((p_config->>'earlyBirdChips')::int, 0);
  IF v_early_chips < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'early_bird_chips_must_not_be_negative');
  END IF;

  v_restart_every := NULLIF(p_config->>'restartEveryMinutes', '')::int;
  -- 10080 = one week (Dan 2026-09-03: MTTs repeat weekly, as a Create Event
  -- checkbox). Was 1440; a day was never long enough for a weekly event.
  IF v_restart_every IS NOT NULL AND (v_restart_every < 5 OR v_restart_every > 10080) THEN
    RETURN jsonb_build_object('success', false, 'error', 'restart_every_minutes_out_of_range');
  END IF;

  v_max_rebuys    := NULLIF(p_config->>'maxRebuys', '')::int;
  v_max_reentries := NULLIF(p_config->>'maxReentries', '')::int;

  v_is_multi_day := COALESCE((p_config->>'isMultiDay')::boolean, false);
  v_total_days   := NULLIF(p_config->>'totalDays', '')::int;
  IF v_is_multi_day THEN
    IF v_total_days IS NULL OR v_total_days < 2 OR v_total_days > 7 THEN
      RETURN jsonb_build_object('success', false, 'error', 'total_days_out_of_range');
    END IF;
  ELSE
    v_total_days := 1;
  END IF;

  v_mb_min_mult := NULLIF(p_config->>'mysteryBountyMin', '')::numeric;
  v_mb_max_mult := NULLIF(p_config->>'mysteryBountyMax', '')::numeric;
  IF (v_mb_min_mult IS NOT NULL OR v_mb_max_mult IS NOT NULL)
     AND v_type <> 'mystery_bounty' THEN
    RETURN jsonb_build_object('success', false, 'error', 'mystery_range_requires_mystery_bounty');
  END IF;
  IF v_type = 'mystery_bounty' THEN
    v_mb_min_mult := COALESCE(v_mb_min_mult, 0.5);
    v_mb_max_mult := COALESCE(v_mb_max_mult, 13);
    IF v_mb_min_mult <= 0 OR v_mb_max_mult < v_mb_min_mult THEN
      RETURN jsonb_build_object('success', false, 'error', 'mystery_bounty_range_invalid');
    END IF;
    v_mb_min_money := round(v_bounty * v_mb_min_mult, 2);
    v_mb_max_money := round(v_bounty * v_mb_max_mult, 2);
  END IF;

  v_sat_target := NULLIF(p_config->>'satelliteTargetId', '')::uuid;
  v_sat_seats  := NULLIF(p_config->>'satelliteSeats', '')::int;
  IF v_sat_seats IS NOT NULL THEN
    IF v_sat_seats < 1 THEN
      RETURN jsonb_build_object('success', false, 'error', 'satellite_seats_invalid');
    END IF;
    IF v_sat_target IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'satellite_seats_requires_target');
    END IF;
  END IF;

  SELECT u.id INTO v_union_id FROM unions u
   WHERE u.id = (SELECT COALESCE(c.union_id,
                        (SELECT uc.union_id FROM union_clubs uc WHERE uc.club_id = c.id LIMIT 1))
                   FROM clubs c WHERE c.id = p_club_id);

  IF (COALESCE((p_config->>'freeBuy')::boolean,false) OR COALESCE((p_config->>'addOnFromStart')::boolean,false))
     AND NOT COALESCE(public.fn_is_free_buy_event((v_buy_in),(v_fee),(CASE WHEN v_type = 'sng' THEN 'SNG' WHEN v_type = 'spin' THEN 'SPIN' ELSE 'MTT' END),(v_variant)),false) THEN
    RAISE EXCEPTION 'Free Buy creation options require an eligible free-entry tournament' USING ERRCODE='22023';
  END IF;
  INSERT INTO tournaments (
    club_id, name, game_type, variant, tournament_type,
    buy_in_amount, buy_in_fee, starting_chips,
    max_players, min_players, current_players, status,
    blind_structure, payout_structure, guaranteed_prize,
    late_reg_levels, late_reg_mins, rebuy_levels,
    start_time,
    is_rebuy, is_reentry, rebuy_cost, rebuy_chips,
    add_on_available, addon_cost, addon_chips, addon_levels,
    is_bounty, bounty_amount, is_pko, is_mystery_bounty,
    spin_type, satellite_target_id, is_xmtt, union_id, is_private,
    short_description, is_vip_only, ban_chat, all_in_or_fold, label_as_new,
    hide_club_name, action_time_seconds, table_size, accelerated_mtt,
    addon_break_minutes, big_blind_ante, authorized_to_register,
    early_bird_enabled, early_bird_chips, bubble_protection,
    final_table_deal_enabled, restart_every_minutes, synchronized_breaks,
    max_rebuys, max_reentries, is_multi_day, total_days,
    mystery_bounty_min, mystery_bounty_max, is_pinned, satellite_seats
  ,
    free_buy, addon_from_start
  ) VALUES (
    p_club_id,
    COALESCE(NULLIF(trim(p_config->>'name'), ''), 'Tournament'),
    COALESCE(p_config->>'gameVariant', 'NLH'),
    v_variant,
    CASE WHEN v_type = 'sng' THEN 'SNG' WHEN v_type = 'spin' THEN 'SPIN' ELSE 'MTT' END,
    v_buy_in, v_fee,
    COALESCE((p_config->>'startingStack')::int, 10000),
    v_max_players, v_min_players, 0, 'REGISTERING',
    v_blinds::text, v_payouts::text,
    GREATEST(0, round(COALESCE((p_config->>'guaranteedPrize')::numeric, 0))),
    COALESCE((p_config->>'lateRegistrationLevels')::int, 0),
    COALESCE((p_config->>'lateRegistrationMinutes')::int, 0),
    COALESCE((p_config->>'lateRegistrationLevels')::int, 0),
    v_start,
    COALESCE((p_config->>'isRebuy')::boolean, false),
    COALESCE((p_config->>'isReentry')::boolean, false),
    GREATEST(0, round(COALESCE((p_config->>'rebuyCost')::numeric, 0))),
    COALESCE((p_config->>'rebuyChips')::int, 0),
    COALESCE((p_config->>'addOnAvailable')::boolean, false),
    GREATEST(0, round(COALESCE((p_config->>'addOnCost')::numeric, 0))),
    COALESCE((p_config->>'addOnChips')::int, 0),
    COALESCE((p_config->>'addOnLevels')::int, 1),
    v_is_bounty, v_bounty,
    v_type = 'progressive_bounty',
    v_type = 'mystery_bounty',
    CASE WHEN v_type = 'spin' THEN COALESCE(p_config->>'spinType', 'standard') ELSE NULL END,
    v_sat_target,
    COALESCE((p_config->>'isXmtt')::boolean, false),
    CASE WHEN v_is_private THEN NULL ELSE v_union_id END,
    v_is_private,
    NULLIF(trim(COALESCE(p_config->>'shortDescription', '')), ''),
    COALESCE((p_config->>'isVipOnly')::boolean, false),
    COALESCE((p_config->>'banChat')::boolean, false),
    COALESCE((p_config->>'allInOrFold')::boolean, false),
    COALESCE((p_config->>'labelAsNew')::boolean, false),
    COALESCE((p_config->>'hideClubName')::boolean, false),
    v_action_time, v_table_size,
    COALESCE((p_config->>'acceleratedMtt')::boolean, false),
    v_addon_break,
    COALESCE((p_config->>'bigBlindAnte')::boolean, false),
    COALESCE((p_config->>'authorizedToRegister')::boolean, false),
    COALESCE((p_config->>'earlyBirdEnabled')::boolean, false),
    v_early_chips,
    COALESCE((p_config->>'bubbleProtection')::boolean, false),
    COALESCE((p_config->>'finalTableDealEnabled')::boolean, false),
    v_restart_every, v_sync_breaks,
    v_max_rebuys, v_max_reentries,
    v_is_multi_day, v_total_days,
    v_mb_min_money, v_mb_max_money,
    COALESCE((p_config->>'isFeatured')::boolean, false),
    v_sat_seats
  ,
    COALESCE((p_config->>'freeBuy')::boolean, false),
    COALESCE((p_config->>'addOnFromStart')::boolean, false)
  )
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('success', true, 'tournament_id', v_id,
                            'buy_in', v_total, 'buy_in_fee', v_fee,
                            'status', 'REGISTERING');
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_deliver_satellite_ticket_exact(p_satellite_id uuid, p_target_id uuid, p_user_id uuid, p_username text, p_position integer, p_ticket_value numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_target public.tournaments%ROWTYPE;
  v_existing public.tournament_players%ROWTYPE;
  v_before_target_pool numeric;
  v_before_target_bounty numeric;
  v_split record;
  v_before_target_rake numeric;
  v_before_source_pool numeric;
  v_open boolean:=false;
  v_count integer;
  v_result jsonb;
  v_registration uuid;
  v_payout uuid;
  v_payout_meta jsonb;
  v_ledger_count integer;
  v_rake_count integer;
  v_target_buyin numeric;
  v_target_fee numeric;
  v_cash_reason text:='target_not_open';
BEGIN
  PERFORM public.fn_ca_lock_settlement_lane_global();
  SELECT * INTO v_target FROM public.tournaments
   WHERE id=p_target_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('delivery','cash','reason','target_missing'); END IF;
  SELECT count(*)::integer INTO v_count FROM public.tournament_players
   WHERE tournament_id=p_target_id;
  v_open:=CASE
    WHEN v_target.status IN ('ANNOUNCED','REGISTERING')
      THEN NOT COALESCE(v_target.prize_pool_finalized,false)
    WHEN v_target.status='RUNNING'
      THEN public.fn_tournament_late_registration_open(p_target_id)
    ELSE false END;
  v_open:=v_open AND (v_target.max_players IS NULL OR v_count<v_target.max_players);
  IF round(GREATEST(COALESCE(v_target.buy_in_amount,0),0)
           +GREATEST(COALESCE(v_target.buy_in_fee,0),0),2)
       <>round(p_ticket_value,2) THEN
    -- The winner owns the frozen advertised value. Never call the historical
    -- seat RPC at a later, different target price: it would debit the source by
    -- today's price. Cash the frozen value instead.
    v_open:=false;
    v_cash_reason:='target_economics_changed';
  END IF;

  SELECT * INTO v_existing FROM public.tournament_players
   WHERE tournament_id=p_target_id AND user_id=p_user_id FOR UPDATE;
  IF FOUND THEN
    IF COALESCE(v_existing.is_satellite_qualifier,false)
       AND v_existing.source_satellite_id=p_satellite_id THEN
      SELECT count(*)::integer,(array_agg(po.id ORDER BY po.id))[1],
             (array_agg(po.metadata ORDER BY po.id))[1]
        INTO v_count,v_payout,v_payout_meta
        FROM public.tournament_payouts po
       WHERE po.tournament_id=p_satellite_id AND po.user_id=p_user_id
         AND po.position=p_position AND po.source='satellite_seat'
         AND round(po.amount,2)=round(p_ticket_value,2)
         AND po.metadata->>'registration_id'=v_existing.id::text;
      v_target_buyin:=CASE
        WHEN COALESCE(v_payout_meta->>'target_buy_in','')~'^[0-9]+([.][0-9]+)?$'
          THEN (v_payout_meta->>'target_buy_in')::numeric ELSE -1 END;
      v_target_fee:=CASE
        WHEN COALESCE(v_payout_meta->>'target_fee','')~'^[0-9]+([.][0-9]+)?$'
          THEN (v_payout_meta->>'target_fee')::numeric ELSE -1 END;
      SELECT count(*)::integer INTO v_ledger_count
        FROM public.chip_ledger l
       WHERE l.idempotency_key='tourney:'||p_satellite_id::text||':seat:'
                               ||p_user_id::text||':pool_transfer'
         AND l.from_type='prize_liability' AND l.from_entity_id=p_satellite_id
         AND l.to_type='prize_liability' AND l.to_entity_id=p_target_id
         AND round(l.amount,2)=round(p_ticket_value,2)
         AND l.metadata->>'registration_id'=v_existing.id::text
         AND CASE WHEN COALESCE(l.metadata->>'moved','')~'^[0-9]+([.][0-9]+)?$'
                  THEN round((l.metadata->>'moved')::numeric,2) ELSE -1 END
             =round(p_ticket_value,2)
         AND CASE WHEN COALESCE(l.metadata->>'unbacked','')~'^[0-9]+([.][0-9]+)?$'
                  THEN round((l.metadata->>'unbacked')::numeric,2) ELSE -1 END=0;
      SELECT count(*)::integer INTO v_rake_count
        FROM public.rake_records rr
       WHERE rr.tournament_id=p_target_id AND rr.source='fn_award_satellite_seat'
         AND rr.metadata->>'satellite_id'=p_satellite_id::text
         AND rr.metadata->>'user_id'=p_user_id::text
         AND rr.metadata->>'registration_id'=v_existing.id::text
         AND round(rr.rake_amount,2)=round(v_target_fee,2)
         AND round(COALESCE(rr.pot_size,0),2)=round(p_ticket_value,2);
      IF v_count<>1
         OR (CASE WHEN COALESCE(v_payout_meta->>'pool_transfer','')~'^[0-9]+([.][0-9]+)?$'
                 THEN round((v_payout_meta->>'pool_transfer')::numeric,2) ELSE -1 END)
            <>round(p_ticket_value,2)
         OR (CASE WHEN COALESCE(v_payout_meta->>'unbacked','')~'^[0-9]+([.][0-9]+)?$'
                 THEN round((v_payout_meta->>'unbacked')::numeric,2) ELSE -1 END)<>0
         OR round(v_target_buyin+v_target_fee,2)<>round(p_ticket_value,2)
         OR v_ledger_count<>1
         OR (v_target_fee>0 AND v_rake_count<>1)
         OR (v_target_fee=0 AND v_rake_count<>0) THEN
        RAISE EXCEPTION 'existing target seat has no exact fully-backed payout event'
          USING ERRCODE='check_violation';
      END IF;
      RETURN jsonb_build_object('delivery','seat','already',true,
        'registration_id',v_existing.id,'payout_id',v_payout);
    ELSIF COALESCE(v_existing.is_satellite_qualifier,false)
          AND v_existing.source_satellite_id IS NULL THEN
      RAISE EXCEPTION 'existing target satellite seat has ambiguous origin'
        USING ERRCODE='check_violation';
    ELSE
      RETURN jsonb_build_object('delivery','cash','reason','seat_already_held_elsewhere');
    END IF;
  END IF;
  -- A CAP IS NOT AN ECONOMIC FAILURE (2026-09-10). The four-table cap is
  -- enforced by trg_enforce_booking_game_cap on the target registration
  -- that fn_award_satellite_seat writes. Attempting the seat and letting
  -- that trigger raise turned one refused chair into a settlement that
  -- could never complete (satellite 9fee70de, 16 hours RUNNING). Take the
  -- same per-user lock the triggers take, read the same count the booking
  -- trigger will read for this target, and deliver the frozen value as
  -- cash - exactly as a closed or full target already does.
  IF v_open THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('table_cap:' || p_user_id::text, 0));
    IF public.fn_concurrent_game_load(p_user_id, NULL, NULL, p_target_id) >= 4 THEN
      v_open := false;
      v_cash_reason := 'four_table_cap';
    END IF;
  END IF;
  IF NOT v_open THEN
    RETURN jsonb_build_object('delivery','cash','reason',v_cash_reason);
  END IF;

  SELECT * INTO v_split FROM public.fn_tournament_entry_split(
    v_target.buy_in_amount,v_target.buy_in_fee,v_target.bounty_amount,
    COALESCE(v_target.is_bounty,false) OR COALESCE(v_target.is_pko,false) OR COALESCE(v_target.is_mystery_bounty,false));
  v_before_target_bounty:=round(COALESCE(v_target.bounty_pool,0),2);
  v_before_target_pool:=round(COALESCE(v_target.prize_pool,0),2);
  v_before_target_rake:=round(COALESCE(v_target.total_rake,0),2);
  SELECT round(COALESCE(t.prize_pool,0),2) INTO v_before_source_pool
    FROM public.tournaments t WHERE t.id=p_satellite_id FOR UPDATE;
  IF v_before_source_pool+0.005<round(p_ticket_value,2) THEN
    RAISE EXCEPTION 'satellite guarantee is not funded for its frozen ticket'
      USING ERRCODE='check_violation';
  END IF;

  v_result:=public.fn_award_satellite_seat(
    p_satellite_id,p_target_id,p_user_id,p_username,p_position);
  IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE
     OR COALESCE((v_result->>'awarded')::boolean,false) IS NOT TRUE
     OR COALESCE((v_result->>'pool_transfer')::numeric,-1)
          <>round(p_ticket_value,2)
     OR COALESCE((v_result->>'unbacked')::numeric,-1)<>0 THEN
    RAISE EXCEPTION 'exact target-seat award refused or wrote incomplete money: %',
      COALESCE(v_result::text,'null') USING ERRCODE='check_violation';
  END IF;
  v_registration:=(v_result->>'registration_id')::uuid;
  IF NOT EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.id=v_registration AND tp.tournament_id=p_target_id
       AND tp.user_id=p_user_id AND tp.source_satellite_id=p_satellite_id
       AND COALESCE(tp.is_satellite_qualifier,false)
  ) THEN
    RAISE EXCEPTION 'seat helper returned without the exact target registration'
      USING ERRCODE='check_violation';
  END IF;
  SELECT count(*)::integer,(array_agg(po.id ORDER BY po.id))[1] INTO v_count,v_payout
    FROM public.tournament_payouts po
   WHERE po.tournament_id=p_satellite_id AND po.user_id=p_user_id
     AND po.position=p_position AND po.source='satellite_seat'
     AND round(po.amount,2)=round(p_ticket_value,2)
     AND po.metadata->>'registration_id'=v_registration::text
     AND round(COALESCE((po.metadata->>'pool_transfer')::numeric,-1),2)
          =round(p_ticket_value,2)
     AND round(COALESCE((po.metadata->>'unbacked')::numeric,-1),2)=0;
  IF v_count<>1
     OR (SELECT round(COALESCE(t.prize_pool,0),2) FROM public.tournaments t
          WHERE t.id=p_target_id)
          <>v_before_target_pool+v_split.prize
     OR (SELECT round(COALESCE(t.bounty_pool,0),2) FROM public.tournaments t
          WHERE t.id=p_target_id) <>v_before_target_bounty+v_split.bounty
     OR (SELECT round(COALESCE(t.total_rake,0),2) FROM public.tournaments t
          WHERE t.id=p_target_id)
          <>v_before_target_rake+round(COALESCE(v_target.buy_in_fee,0),2)
     OR (SELECT round(COALESCE(t.prize_pool,0),2) FROM public.tournaments t
          WHERE t.id=p_satellite_id)
          <>v_before_source_pool-round(p_ticket_value,2) THEN
    RAISE EXCEPTION 'target seat, payout and pool transfer are not one exact event'
      USING ERRCODE='check_violation';
  END IF;
  RETURN jsonb_build_object('delivery','seat','already',false,
    'registration_id',v_registration,'payout_id',v_payout);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_create_tournament(p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_arena uuid; v_id uuid;
  v_total bigint; v_fee bigint; v_buy_in bigint; v_ratio numeric;
  v_max integer; v_min integer; v_type text; v_variant text; v_game text;
  v_start timestamptz; v_payouts jsonb; v_blinds jsonb; v_pct numeric; v_chips integer;
  v_rebuy boolean; v_reentry boolean; v_addon boolean; v_rebuy_cost bigint; v_addon_cost bigint;
  v_rebuy_num numeric; v_addon_num numeric; v_name text;
  v_is_bounty boolean; v_bounty_num numeric; v_bounty bigint;
  v_mystery boolean; v_mb_activation text; v_mb_profile text; v_mb_value numeric; v_mb_top numeric;
  v_mb_pool numeric; v_mb_regular numeric; v_mb_min_mult numeric; v_mb_max_mult numeric;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='28000'; END IF;
  IF NOT public.fn_is_platform_admin() THEN
    RAISE EXCEPTION 'diamond_tournament_staff_only' USING ERRCODE='42501';
  END IF;
  SELECT c.id INTO v_arena FROM public.clubs c
   WHERE c.asset='diamonds' AND c.is_platform IS TRUE AND c.union_id IS NULL LIMIT 1;
  IF v_arena IS NULL THEN RAISE EXCEPTION 'diamond_arena_not_found' USING ERRCODE='P0002'; END IF;
  IF p_config IS NULL OR jsonb_typeof(p_config)<>'object' THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_configuration' USING ERRCODE='22023';
  END IF;

  v_type := lower(COALESCE(p_config->>'type','mtt'));
  IF v_type NOT IN ('mtt','sng','bounty','progressive_bounty','mystery_bounty') THEN
    -- satellite, spin: later Phase 9 pieces.
    RAISE EXCEPTION 'diamond_tournament_format_not_open' USING ERRCODE='55000';
  END IF;
  IF COALESCE((p_config->>'guarantee')::numeric,0)<>0 OR COALESCE((p_config->>'satelliteTargetId')::text,'')<>''
     OR COALESCE((p_config->>'freeBuy')::boolean,false) THEN
    RAISE EXCEPTION 'diamond_tournament_format_not_open' USING ERRCODE='55000';
  END IF;
  -- A knockout bounty is a format, not a flag: the flat bounty rides on a
  -- 'bounty', 'progressive_bounty' or 'mystery_bounty' event and on nothing else.
  v_is_bounty := v_type IN ('bounty','progressive_bounty','mystery_bounty');
  v_mystery := v_type = 'mystery_bounty';
  v_bounty_num := COALESCE((p_config->>'bountyAmount')::numeric,0);
  IF NOT v_is_bounty AND (v_bounty_num<>0 OR COALESCE((p_config->>'isBounty')::boolean,false)) THEN
    RAISE EXCEPTION 'diamond_tournament_bounty_requires_a_bounty_format' USING ERRCODE='22023';
  END IF;
  IF NOT v_mystery AND (p_config ? 'mysteryBountyMin' OR p_config ? 'mysteryBountyMax' OR p_config ? 'mysteryBounty') THEN
    RAISE EXCEPTION 'diamond_tournament_mystery_requires_a_mystery_format' USING ERRCODE='22023';
  END IF;
  v_game := upper(btrim(COALESCE(p_config->>'gameVariant','NLH')));
  IF v_game NOT IN ('NLH','PLO4','PLO5','PLO6','PLO8','SHORT_DECK','FLH','FLO8') THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_supported_game' USING ERRCODE='22023';
  END IF;

  v_total := COALESCE((p_config->>'buyIn')::numeric,0);
  IF (p_config->>'buyIn')::numeric IS DISTINCT FROM v_total::numeric OR v_total<1 OR v_total>2147483647 THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_whole_positive_buy_in' USING ERRCODE='22023';
  END IF;
  v_max := COALESCE((p_config->>'maxPlayers')::int,0);
  IF v_max<2 OR v_max>10000 THEN RAISE EXCEPTION 'diamond_tournament_requires_a_real_field' USING ERRCODE='22023'; END IF;
  v_min := GREATEST(COALESCE((p_config->>'minPlayers')::int,3),2);
  IF v_min>v_max THEN v_min := v_max; END IF;
  -- The fee rule the recovery fee already states, at this entry's own unit.
  v_ratio := CASE WHEN v_max<=2 THEN 0.05 ELSE 0.10 END;
  v_fee := public.fn_ca_unit_floor_cents(round(v_total*100*v_ratio)::bigint, 100)/100;
  v_buy_in := v_total - v_fee;
  IF v_buy_in<1 THEN RAISE EXCEPTION 'diamond_tournament_buy_in_below_one_diamond' USING ERRCODE='22023'; END IF;
  -- The chip door's bounty rule at the Diamond unit: a whole bounty of at
  -- least one Diamond, no larger than the buy-in after the fee (the prize
  -- part is what remains; it may be zero, as the chip split allows).
  IF v_is_bounty THEN
    IF v_bounty_num<>trunc(v_bounty_num) OR v_bounty_num<1 OR v_bounty_num>v_buy_in THEN
      RAISE EXCEPTION 'diamond_tournament_requires_a_whole_bounty_within_the_buy_in' USING ERRCODE='22023';
    END IF;
    v_bounty := v_bounty_num;
  ELSE
    v_bounty := 0;
  END IF;
  -- The mystery rules are the chip configuration door's rules
  -- (fn_apply_mystery_bounty_config), stamped here because that door consults
  -- a club owner the arena does not have. The lobby's advertised range is the
  -- chip door's multipliers on the flat bounty, in whole Diamonds.
  IF v_mystery THEN
    v_mb_activation := COALESCE(p_config->'mysteryBounty'->>'activation', 'at_the_money');
    IF v_mb_activation NOT IN ('at_the_money','percent_field','player_count') THEN
      RAISE EXCEPTION 'diamond_mystery_bounty_bad_activation_mode' USING ERRCODE='22023';
    END IF;
    v_mb_profile := COALESCE(p_config->'mysteryBounty'->>'profile', 'classic');
    IF v_mb_profile NOT IN ('balanced','classic','jackpot') THEN
      RAISE EXCEPTION 'diamond_mystery_bounty_bad_profile' USING ERRCODE='22023';
    END IF;
    v_mb_value := (p_config->'mysteryBounty'->>'activationValue')::numeric;
    IF v_mb_activation = 'percent_field' AND (COALESCE(v_mb_value,0) <= 0 OR v_mb_value > 100) THEN
      RAISE EXCEPTION 'diamond_mystery_bounty_activation_percent_out_of_range' USING ERRCODE='22023';
    END IF;
    IF v_mb_activation = 'player_count' AND COALESCE(v_mb_value,0) < 2 THEN
      RAISE EXCEPTION 'diamond_mystery_bounty_activation_count_too_small' USING ERRCODE='22023';
    END IF;
    v_mb_top := COALESCE((p_config->'mysteryBounty'->>'topPercent')::numeric, 20);
    IF v_mb_top <= 0 OR v_mb_top > 100 THEN
      RAISE EXCEPTION 'diamond_mystery_bounty_top_percent_out_of_range' USING ERRCODE='22023';
    END IF;
    v_mb_pool := COALESCE((p_config->'mysteryBounty'->>'poolPercent')::numeric, 50);
    v_mb_regular := COALESCE((p_config->'mysteryBounty'->>'regularPoolPercent')::numeric, 100 - v_mb_pool);
    IF v_mb_pool < 0 OR v_mb_regular < 0 OR v_mb_pool + v_mb_regular <= 0 THEN
      RAISE EXCEPTION 'diamond_mystery_bounty_pool_split_invalid' USING ERRCODE='22023';
    END IF;
    v_mb_min_mult := COALESCE(NULLIF(p_config->>'mysteryBountyMin','')::numeric, 0.5);
    v_mb_max_mult := COALESCE(NULLIF(p_config->>'mysteryBountyMax','')::numeric, 13);
    IF v_mb_min_mult <= 0 OR v_mb_max_mult < v_mb_min_mult THEN
      RAISE EXCEPTION 'diamond_mystery_bounty_range_invalid' USING ERRCODE='22023';
    END IF;
  END IF;

  v_chips := COALESCE((p_config->>'startingStack')::int, 10000);
  IF v_chips<1 THEN RAISE EXCEPTION 'diamond_tournament_requires_a_starting_stack' USING ERRCODE='22023'; END IF;
  v_blinds := COALESCE(p_config->'blindStructure','[]'::jsonb);
  v_payouts := COALESCE(p_config->'payoutStructure','[]'::jsonb);
  IF jsonb_typeof(v_blinds)<>'array' OR jsonb_array_length(v_blinds)=0 THEN
    RAISE EXCEPTION 'blind_structure_required' USING ERRCODE='22023';
  END IF;
  IF jsonb_typeof(v_payouts)<>'array' OR jsonb_array_length(v_payouts)=0 THEN
    RAISE EXCEPTION 'payout_structure_required' USING ERRCODE='22023';
  END IF;
  SELECT COALESCE(sum((e->>'percentage')::numeric),0) INTO v_pct FROM jsonb_array_elements(v_payouts) e;
  IF abs(v_pct-100)>1 THEN RAISE EXCEPTION 'payouts_must_total_100' USING ERRCODE='22023'; END IF;
  IF jsonb_array_length(v_payouts)>v_max THEN RAISE EXCEPTION 'more_paid_places_than_players' USING ERRCODE='22023'; END IF;
  v_start := COALESCE((p_config->>'startTime')::timestamptz, now()+interval '1 minute');
  v_rebuy := COALESCE((p_config->>'rebuy')::boolean,false);
  v_reentry := COALESCE((p_config->>'reentry')::boolean,v_rebuy);
  v_addon := COALESCE((p_config->>'addOn')::boolean,false);
  v_rebuy_num := COALESCE((p_config->>'rebuyCost')::numeric, v_total);
  v_addon_num := COALESCE((p_config->>'addonCost')::numeric, v_total);
  IF (v_rebuy OR v_reentry) AND (v_rebuy_num <> trunc(v_rebuy_num) OR v_rebuy_num < 1 OR v_rebuy_num > 2147483647) THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_whole_rebuy_cost' USING ERRCODE='22023';
  END IF;
  IF v_addon AND (v_addon_num <> trunc(v_addon_num) OR v_addon_num < 1 OR v_addon_num > 2147483647) THEN
    RAISE EXCEPTION 'diamond_tournament_requires_a_whole_addon_cost' USING ERRCODE='22023';
  END IF;
  v_rebuy_cost := v_rebuy_num; v_addon_cost := v_addon_num;
  v_name := COALESCE(NULLIF(btrim(p_config->>'name'),''),'Diamond Tournament');
  v_variant := CASE v_type WHEN 'sng' THEN 'sng' WHEN 'bounty' THEN 'bounty'
                           WHEN 'progressive_bounty' THEN 'progressive_bounty'
                           WHEN 'mystery_bounty' THEN 'mystery_bounty' ELSE 'freezeout' END;

  INSERT INTO public.tournaments (
    club_id, union_id, name, game_type, variant, tournament_type,
    buy_in_amount, buy_in_fee, guaranteed_prize, starting_chips, max_players, table_size, min_players,
    current_players, status, blind_structure, payout_structure, start_time,
    late_reg_levels, late_reg_mins, is_bounty, is_pko, is_mystery_bounty, bounty_amount,
    mystery_bounty_min, mystery_bounty_max,
    mystery_bounty_activation, mystery_bounty_activation_value, mystery_bounty_profile,
    mystery_bounty_top_percent, mystery_bounty_pool_percent, mystery_bounty_regular_pool_percent,
    is_rebuy, is_reentry, rebuy_cost, rebuy_chips, rebuy_levels, max_rebuys, max_reentries,
    add_on_available, addon_cost, addon_chips, addon_levels,
    payout_percent, free_buy, is_private, action_time_seconds)
  VALUES (
    v_arena, NULL, v_name, v_game, v_variant, CASE WHEN v_type='sng' THEN 'SNG' ELSE 'MTT' END,
    v_buy_in, v_fee, 0, v_chips, v_max, LEAST(9, GREATEST(2, v_max)), v_min,
    0, 'REGISTERING', v_blinds::text, v_payouts::text, v_start,
    COALESCE((p_config->>'lateRegLevels')::int, CASE WHEN v_type='sng' THEN 0 ELSE 8 END), 8,
    v_is_bounty, v_type='progressive_bounty', v_mystery, v_bounty,
    CASE WHEN v_mystery THEN trunc(v_bounty * v_mb_min_mult) ELSE 0 END,
    CASE WHEN v_mystery THEN trunc(v_bounty * v_mb_max_mult) ELSE 0 END,
    CASE WHEN v_mystery THEN v_mb_activation END, CASE WHEN v_mystery THEN v_mb_value END,
    CASE WHEN v_mystery THEN v_mb_profile END,
    CASE WHEN v_mystery THEN v_mb_top END, CASE WHEN v_mystery THEN v_mb_pool END,
    CASE WHEN v_mystery THEN v_mb_regular END,
    v_rebuy, v_reentry, CASE WHEN v_rebuy OR v_reentry THEN v_rebuy_cost ELSE 0 END,
    CASE WHEN v_rebuy OR v_reentry THEN v_chips ELSE 0 END, CASE WHEN v_rebuy OR v_reentry THEN 6 ELSE 4 END,
    CASE WHEN v_rebuy THEN COALESCE((p_config->>'maxRebuys')::int,2) ELSE 0 END,
    CASE WHEN v_reentry THEN COALESCE((p_config->>'maxReentries')::int,1) ELSE 0 END,
    v_addon, CASE WHEN v_addon THEN v_addon_cost ELSE 0 END, CASE WHEN v_addon THEN v_chips ELSE 0 END, 1,
    CASE WHEN (p_config->>'payoutPercent')::int IN (10,15,20) THEN (p_config->>'payoutPercent')::smallint ELSE 10 END,
    false, false, 15)
  RETURNING id INTO v_id;

  -- The row this door wrote must be one the money path will price: whole
  -- Diamonds everywhere, and the unit rule must recognise it.
  IF public.fn_ca_tournament_unit_cents(v_id) <> 100 OR NOT public.fn_poker_diamond_tournament(v_id) THEN
    RAISE EXCEPTION 'diamond_tournament_would_not_be_recognised' USING ERRCODE='23514';
  END IF;
  RETURN jsonb_build_object('success',true,'tournamentId',v_id,'id',v_id,'buy_in_amount',v_buy_in,'buy_in_fee',v_fee,
    'total',v_total,'bounty_amount',v_bounty,'is_mystery_bounty',v_mystery,'asset','diamonds');
END $function$

CREATE OR REPLACE FUNCTION public.fn_poker_diamond_tournament_unregister(p_tournament_id uuid, p_user_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE; v_reg public.tournament_players%ROWTYPE;
  v_refund jsonb; v_players_before integer; v_rows integer;
  v_prior public.poker_diamond_tournament_ledger%ROWTYPE; v_prior_reg uuid;
  v_authority text := 'scheduled_clock';
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'tournament, player and request ids are required' USING ERRCODE='22004';
  END IF;
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  SELECT * INTO v_t FROM public.tournaments t WHERE t.id=p_tournament_id FOR UPDATE;
  IF v_t.id IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','tournament_not_found'); END IF;
  IF NOT public.fn_poker_diamond_tournament(p_tournament_id) THEN
    RAISE EXCEPTION 'diamond_asset_required' USING ERRCODE='23514';
  END IF;

  -- A withdrawal that already happened answers with what it did: the same
  -- receipt the first answer carried, rebuilt from the refund ledger row
  -- (its registration id from the entry row of the same custody), so the
  -- client's one exact replay after a lost response is a receipt. The chip
  -- authority replays its stored receipt the same way, past the clock too.
  SELECT l.* INTO v_prior FROM public.poker_diamond_tournament_ledger l
   WHERE l.tournament_id=p_tournament_id AND l.user_id=p_user_id AND l.kind='refund'
     AND l.request->>'request_id'=p_request_id::text
   ORDER BY l.id LIMIT 1;
  IF FOUND THEN
    SELECT e.registration_id INTO v_prior_reg FROM public.poker_diamond_tournament_ledger e
     WHERE e.custody_id=v_prior.custody_id AND e.kind='entry'
     ORDER BY e.id LIMIT 1;
    RETURN jsonb_build_object('ok',true,'idempotent',true,'replayed',true,'fully_settled',true,'remaining',0,
      'request_id',p_request_id,
      'refunded_diamonds',v_prior.amount,'refund_prize',v_prior.prize_part,
      'refund_bounty',v_prior.bounty_part,'refund_fee',v_prior.fee_part,
      'registration_id',v_prior_reg,'custody_id',v_prior.custody_id,'obligation_id',v_prior.obligation_id,
      'asset','diamonds','diamonds_after',(SELECT p.diamonds FROM public.profiles p WHERE p.id=p_user_id));
  END IF;

  -- The start authority is the chip authority's. A scheduled event closes at
  -- its clock. A spin or a heads-up sit-and-go is seat-first: start_time is
  -- only its fill-window deadline, and it closes when it actually starts. A
  -- launch releasing a registrant it could not seat names its incomplete
  -- receipt through app.ca_launch_release_launch_id; it is past the clock by
  -- design and is held to the seat-first proofs instead. A persisted hand
  -- closes every product.
  IF v_t.satellite_target_id IS NULL
     AND upper(COALESCE(v_t.tournament_type::text,''))<>'SATELLITE'
     AND (lower(COALESCE(v_t.variant::text,''))='spin'
       OR upper(COALESCE(v_t.tournament_type::text,''))='SPIN') THEN
    v_authority := 'spin_actual_start';
  ELSIF v_t.satellite_target_id IS NULL
     AND upper(COALESCE(v_t.tournament_type::text,''))='SNG'
     AND lower(COALESCE(v_t.variant::text,''))<>'spin'
     AND COALESCE(v_t.max_players,0)=2 THEN
    v_authority := 'heads_up_sng_actual_start';
  END IF;
  IF v_authority='scheduled_clock' AND EXISTS (
       SELECT 1 FROM public.tournament_launch_receipts r
        WHERE r.tournament_id=p_tournament_id
          AND r.completed_at IS NULL
          AND r.launch_id::text=NULLIF(current_setting('app.ca_launch_release_launch_id',true),'')) THEN
    v_authority := 'launch_release';
  END IF;
  IF upper(COALESCE(v_t.status,'')) NOT IN ('ANNOUNCED','REGISTERING') OR v_t.started_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_started');
  END IF;
  IF EXISTS (SELECT 1 FROM public.hand_history hh WHERE hh.tournament_id=p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tables ht JOIN public.hand_history hh ON hh.table_id=ht.id
                 WHERE ht.tournament_id=p_tournament_id) THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_started');
  END IF;
  IF v_authority='scheduled_clock' THEN
    IF v_t.start_time IS NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','registration_schedule_unset');
    END IF;
    IF clock_timestamp()>=v_t.start_time THEN
      RETURN jsonb_build_object('ok',false,'reason','tournament_started');
    END IF;
  ELSIF EXISTS (SELECT 1 FROM public.tournament_launch_receipts r
                 WHERE r.tournament_id=p_tournament_id AND r.completed_at IS NOT NULL) THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_started');
  END IF;

  SELECT * INTO v_reg FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id FOR UPDATE;
  IF v_reg.id IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','not_registered'); END IF;
  IF v_reg.status::text NOT IN ('registered','playing') THEN
    RETURN jsonb_build_object('ok',false,'reason','not_registered');
  END IF;
  SELECT count(*)::integer INTO v_players_before FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.status::text IN ('registered','playing');

  -- Money first: the release is the part that can refuse.
  v_refund := public.fn_poker_diamond_tournament_refund(
    p_tournament_id, p_user_id, 'unregister', 'fn_unregister_from_tournament', p_request_id);

  -- The same roster effects the chip authority produces, in the same order.
  UPDATE public.table_seats s
     SET left_at=transaction_timestamp(),status='left',leave_pending=false,
         is_sitting_out=false,is_away=false,sit_out_at=NULL,scheduled_leave_hands=NULL
   WHERE s.user_id=p_user_id AND s.left_at IS NULL
     AND EXISTS(SELECT 1 FROM public.tables tb WHERE tb.id=s.table_id AND tb.tournament_id=p_tournament_id);
  UPDATE public.tables tb
     SET current_players=(SELECT count(*) FROM public.table_seats s WHERE s.table_id=tb.id AND s.left_at IS NULL),
         updated_at=now()
   WHERE tb.tournament_id=p_tournament_id;
  DELETE FROM public.tournament_players tp WHERE tp.id=v_reg.id;
  UPDATE public.tournaments
     SET current_players=v_players_before-1,
         prize_pool=round(COALESCE(prize_pool,0)-(v_refund->>'refund_prize')::numeric,2),
         bounty_pool=round(COALESCE(bounty_pool,0)-(v_refund->>'refund_bounty')::numeric,2),
         total_rake=round(COALESCE(total_rake,0)-(v_refund->>'refund_fee')::numeric,2),
         updated_at=now()
   WHERE id=p_tournament_id;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN RAISE EXCEPTION 'tournament vanished during unregistration' USING ERRCODE='40001'; END IF;
  RETURN jsonb_build_object('ok',true,'fully_settled',true,'remaining',0,'request_id',p_request_id,
    'refunded_diamonds',(v_refund->>'paid')::numeric,'refund_prize',(v_refund->>'refund_prize')::numeric,
    'refund_bounty',(v_refund->>'refund_bounty')::numeric,'refund_fee',(v_refund->>'refund_fee')::numeric,
    'registration_id',v_reg.id,'custody_id',v_refund->>'custody_id','obligation_id',v_refund->>'obligation_id',
    'asset','diamonds','diamonds_after',(SELECT p.diamonds FROM public.profiles p WHERE p.id=p_user_id));
END $function$

CREATE OR REPLACE FUNCTION public.fn_register_for_tournament_with_ticket(p_tournament_id uuid, p_ticket_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_gate jsonb;
BEGIN
  v_gate:=public.fn_ca_lock_tournament_seat_acquisition(
    p_tournament_id,NULL,auth.uid());
  IF COALESCE((v_gate->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN v_gate;
  END IF;
  RETURN public.fn_register_for_tournament_with_ticket_before_terminal_gate(
    p_tournament_id,p_ticket_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_seat_horse_in_seat_first_game_before_maintenance_gate(p_tournament_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_t       record;
  v_table   record;
  v_seat    int;
  v_reg     jsonb;
  v_taken   int;
  v_already boolean;
  v_seated  int;
  v_stack   numeric;
BEGIN
  PERFORM set_config('app.money_path', 'fn_seat_horse_in_seat_first_game', true); -- CHIP STANDARD C2: sanctioned seat creator (trg_ca_guard_seat_creation)

  /* THE PLAYER'S MISSIONS LOCK BEFORE THE GAME ROW (20260906). Seating ends
     with UPDATE tournament_players ... status = 'playing', whose statement
     trigger fn_daily_missions_tournament_registered_updated takes the
     per-player advisory lock 'daily-missions-user:<id>' and the player's
     profiles row. A hand this horse is playing elsewhere writes hand_history
     at the same moment and its trigger takes that same lock FIRST, then waits
     on a row this function holds. Rows-then-lock here, lock-then-rows there:
     12 deadlocks a day, and the victim on the other side was the hand
     record. Take the lock first, in the same order as the hand path; the
     trigger re-takes it later at no cost (advisory xact locks re-enter). */
  PERFORM public.fn_lock_daily_mission_user(p_user_id);

  SELECT id, status, variant, max_players, starting_chips, name
    INTO v_t FROM public.tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found');
  END IF;

  IF NOT (COALESCE(v_t.variant,'') = 'spin' OR COALESCE(v_t.max_players,0) <= 2) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_seat_first_game');
  END IF;

  -- Identical to the human seat. See CLAUDE.md 10.5.
  v_stack := COALESCE(v_t.starting_chips, 0);

  SELECT id, max_players INTO v_table
    FROM public.tables
   WHERE id = public.fn_tournament_primary_table(p_tournament_id);
  IF v_table.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_table');
  END IF;

  IF EXISTS (SELECT 1 FROM public.table_seats
              WHERE table_id = v_table.id AND user_id = p_user_id AND left_at IS NULL) THEN
    RETURN jsonb_build_object('ok', true, 'already_seated', true);
  END IF;

  SELECT s INTO v_seat
    FROM generate_series(1, COALESCE(NULLIF(v_table.max_players,0), v_t.max_players, 3)) s
   WHERE NOT EXISTS (
     SELECT 1 FROM public.table_seats ts
      WHERE ts.table_id = v_table.id AND ts.seat_number = s AND ts.left_at IS NULL
   )
   ORDER BY s LIMIT 1;

  IF v_seat IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_full');
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.tournament_players
                  WHERE tournament_id = p_tournament_id AND user_id = p_user_id)
    INTO v_already;

  IF NOT v_already THEN
    v_reg := public.fn_register_horse_for_tournament(p_tournament_id, p_user_id);
    IF COALESCE((v_reg->>'ok')::boolean, false) IS NOT TRUE
       AND COALESCE(v_reg->>'reason','') <> 'already_registered' THEN
      RETURN jsonb_build_object('ok', false, 'reason', COALESCE(v_reg->>'reason','register_failed'));
    END IF;
  END IF;

  UPDATE public.table_seats
  /* is_sitting_out = false: THE ONE LINE THAT DIFFERED FROM THE HUMAN DOOR
     (2026-09-11). fn_take_seat_and_buy_in revives a vacated seat row with
     is_sitting_out = false; this door revived it without touching the column,
     so a horse handed a chair that a sitting-out player vacated started its
     game sat out. CLAUDE.md 10.5: identical, not equivalent. Zero live
     occurrences when it was found (seat-first tables are fresh per game and
     rarely re-seat a vacated row), so this is the mirror, not an incident. */
     SET user_id        = p_user_id,
         left_at        = NULL,
         stack          = v_stack,
         joined_at      = now(),
         is_sitting_out = false
   WHERE table_id = v_table.id
     AND seat_number = v_seat
     AND left_at IS NOT NULL;
  GET DIAGNOSTICS v_seated = ROW_COUNT;

  IF v_seated = 0 THEN
    BEGIN
      INSERT INTO public.table_seats (table_id, user_id, seat_number, stack)
      VALUES (v_table.id, p_user_id, v_seat, v_stack);
    EXCEPTION WHEN unique_violation THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'seat_taken');
    END;
  END IF;

  UPDATE public.tournament_players
     SET status = 'playing', chips = v_stack, table_id = v_table.id, seat_number = v_seat
   WHERE tournament_id = p_tournament_id AND user_id = p_user_id;

  v_taken := COALESCE(public.fn_sync_seat_first_player_count(p_tournament_id), 0);

  RETURN jsonb_build_object('ok', true, 'table_id', v_table.id, 'seat_number', v_seat,
    'stack', v_stack,
    'seats_taken', v_taken, 'reused_registration', v_already, 'reused_seat', v_seated > 0,
    'seats', COALESCE(NULLIF(v_table.max_players,0), v_t.max_players, 3));
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_take_seat_and_buy_in_before_maintenance_announcement_gate(p_table_id uuid, p_seat_number integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid        uuid := auth.uid();
  v_tbl        record;
  v_t          record;
  v_reg        jsonb;
  v_seat_cap   integer;
  v_taken      integer;
  v_mine       integer;
  v_stack      numeric;
  v_err        text;
BEGIN
  PERFORM set_config('app.money_path', 'fn_take_seat_and_buy_in', true); -- CHIP STANDARD C2: sanctioned seat creator (trg_ca_guard_seat_creation)
  -- ── A DEAD SESSION MOVES NO MONEY (Dan 2026-09-03) ────────────────────
  -- "I WAS LOGGED OUT, BUT SOMEHOW ABLE TO SIT DOWN AND BUY CHIPS AND GET
  -- DEALT A HAND. THAT CAN NEVER HAPPEN." It could, because this project
  -- issues SEVEN-DAY access tokens and PostgREST verifies a JWT locally -
  -- signature and exp only. It never asks GoTrue whether the session behind
  -- that token still exists, so signing out left a bearer token that kept
  -- spending real chips as its owner for the rest of the week. The engine
  -- was never fooled (it verifies through auth.getUser, which checks the
  -- session), only the database was. fn_caller_session_is_live closes that
  -- gap at the money door itself.
  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'SESSION_REVOKED: this session is signed out - sign in again'
      USING ERRCODE = '28000';
  END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_take_seat_and_buy_in requires an authenticated caller'
      USING ERRCODE = '28000';
  END IF;

  SELECT id, tournament_id, max_players, status
    INTO v_tbl FROM public.tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;
  IF v_tbl.tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_game_table');
  END IF;
  IF v_tbl.status = 'closed' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_closed');
  END IF;

  SELECT id, status, variant, max_players, starting_chips, name
    INTO v_t FROM public.tournaments WHERE id = v_tbl.tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'game_not_found');
  END IF;

  IF NOT (COALESCE(v_t.variant, '') = 'spin' OR COALESCE(v_t.max_players, 0) <= 2) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_seat_first_game');
  END IF;

  -- The chips this seat is buying. Known now, because the board decides it.
  v_stack := COALESCE(v_t.starting_chips, 0);

  v_seat_cap := COALESCE(NULLIF(v_tbl.max_players, 0), v_t.max_players, 3);

  IF p_seat_number IS NULL OR p_seat_number < 1 OR p_seat_number > v_seat_cap THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_seat');
  END IF;

  SELECT seat_number INTO v_mine
    FROM public.table_seats
   WHERE table_id = p_table_id AND user_id = v_uid AND left_at IS NULL LIMIT 1;
  IF v_mine IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'already_seated', true,
      'table_id', p_table_id, 'seat_number', v_mine);
  END IF;

  IF v_t.status NOT IN ('ANNOUNCED', 'REGISTERING') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'game_already_started');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.table_seats
     WHERE table_id = p_table_id AND seat_number = p_seat_number AND left_at IS NULL
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'seat_taken');
  END IF;

  PERFORM public.fn_sync_seat_first_player_count(v_t.id);

  v_reg := public.fn_register_for_tournament(v_t.id, true);
  IF COALESCE((v_reg->>'ok')::boolean, false) IS NOT TRUE
     AND COALESCE(v_reg->>'reason', '') <> 'already_registered' THEN
    RETURN jsonb_build_object('ok', false,
      'reason', COALESCE(v_reg->>'reason', 'buy_in_failed'));
  END IF;

  UPDATE public.tournament_players
     SET status = 'playing', chips = v_stack, table_id = p_table_id, seat_number = p_seat_number
   WHERE tournament_id = v_t.id AND user_id = v_uid;

  UPDATE public.table_seats
     SET user_id = v_uid, stack = v_stack, left_at = NULL, joined_at = now(), is_sitting_out = false
   WHERE table_id = p_table_id AND seat_number = p_seat_number AND left_at IS NOT NULL;

  IF NOT FOUND THEN
    BEGIN
      INSERT INTO public.table_seats (table_id, user_id, seat_number, stack)
      VALUES (p_table_id, v_uid, p_seat_number, v_stack);
    EXCEPTION WHEN unique_violation THEN
      RAISE EXCEPTION 'seat_taken' USING ERRCODE = '55000';
    END;
  END IF;

  v_taken := COALESCE(public.fn_sync_seat_first_player_count(v_t.id), 0);
  IF v_taken = 0 THEN
    SELECT count(*) INTO v_taken FROM public.table_seats
     WHERE table_id = p_table_id AND left_at IS NULL;
  END IF;

  RETURN jsonb_build_object('ok', true, 'table_id', p_table_id,
    'seat_number', p_seat_number, 'stack', v_stack, 'seat_reserved', true,
    'seats_taken', v_taken, 'seats_needed', v_seat_cap,
    'starts_now', v_taken >= v_seat_cap,
    'cost', COALESCE((v_reg->>'cost')::numeric, 0))
    -- DIAMOND PHASE 8: a Diamond seat purchase names its asset and the
    -- wallet after the charge, as the lobby receipt does, so the client can
    -- move the balance it shows. Absent on the already_registered answer,
    -- which carries no charge.
    || CASE WHEN v_reg ? 'asset'
         THEN jsonb_build_object('asset', v_reg->'asset', 'diamonds_after', v_reg->'diamonds_after')
         ELSE '{}'::jsonb END;

EXCEPTION
  WHEN sqlstate '55000' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'seat_taken');
  WHEN sqlstate '23514' THEN
    GET STACKED DIAGNOSTICS v_err = MESSAGE_TEXT;
    IF v_err LIKE '%FOUR TABLE LIMIT%' THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'table_limit_reached',
        'limit', 4);
    END IF;
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_tournament_atomic_register(p_user_id uuid, p_club_id uuid, p_tournament_id uuid, p_buy_in numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_tourn        record;
  v_balance      numeric;
  v_existing     uuid;
  v_display_name text;
  v_reg_id       uuid;
  v_count        integer;
  v_buy_in       numeric;
  v_fee          numeric;
  v_total        numeric;
BEGIN
  SELECT * INTO v_tourn FROM tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF v_tourn.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tournament not found');
  END IF;

  IF v_tourn.status NOT IN ('scheduled', 'registering', 'running') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Registration not open');
  END IF;

  IF v_tourn.max_players IS NOT NULL AND COALESCE(v_tourn.current_players, 0) >= v_tourn.max_players THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tournament full');
  END IF;

  SELECT id INTO v_existing FROM tournament_registrations
    WHERE tournament_id = p_tournament_id AND user_id = p_user_id AND status = 'registered';
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Already registered');
  END IF;

  -- Authoritative buy-in / fee come from the LOCKED tournament config, not the
  -- client-passed p_buy_in (defense in depth). Prize pool NEVER includes fee.
  v_buy_in := COALESCE(v_tourn.buy_in_amount, p_buy_in, 0);
  v_fee    := COALESCE(v_tourn.buy_in_fee, 0);
  v_total  := v_buy_in + v_fee;

  SELECT COALESCE(chip_balance, 0) INTO v_balance
    FROM club_members WHERE club_id = p_club_id AND user_id = p_user_id FOR UPDATE;
  IF v_balance IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not a member of this club');
  END IF;

  IF v_balance < v_total THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient chips',
                              'balance', v_balance, 'required', v_total);
  END IF;

  -- Debit the FULL charge (buy-in + fee).
  UPDATE club_members
     SET chip_balance = chip_balance - v_total::integer, updated_at = NOW()
   WHERE club_id = p_club_id AND user_id = p_user_id;

  SELECT COALESCE(display_name, username, 'Player') INTO v_display_name
    FROM profiles WHERE id = p_user_id;

  INSERT INTO tournament_registrations (
    id, tournament_id, user_id, status, registered_at, display_name,
    buy_in_amount, buy_in_fee
  ) VALUES (
    gen_random_uuid(), p_tournament_id, p_user_id, 'registered', NOW(),
    COALESCE(v_display_name, 'Player'), v_buy_in, v_fee
  ) RETURNING id INTO v_reg_id;

  -- Prize pool gets the buy-in ONLY (excludes fee); fee accrues to total_rake.
  UPDATE tournaments
     SET current_players = COALESCE(current_players, 0) + 1,
         prize_pool      = COALESCE(prize_pool, 0) + v_buy_in,
         total_rake      = COALESCE(total_rake, 0) + v_fee,
         updated_at      = NOW()
   WHERE id = p_tournament_id
   RETURNING COALESCE(current_players, 0) INTO v_count;

  INSERT INTO chip_transactions (
    id, club_id, from_user_id, to_user_id, amount,
    transaction_type, notes, balance_after, created_at
  ) VALUES (
    gen_random_uuid(), p_club_id, p_user_id, NULL, v_total,
    'tournament_buyin',
    'Tournament buy-in: ' || p_tournament_id::text || ' (buyin ' || v_buy_in || ' + fee ' || v_fee || ')',
    v_balance - v_total, NOW()
  );

  RETURN jsonb_build_object(
    'success', true, 'registration_id', v_reg_id, 'registered_count', v_count,
    'buy_in', v_buy_in, 'fee', v_fee, 'total_charged', v_total,
    'balance_after', v_balance - v_total
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_tournament_entry_cap_reached(p_tournament_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cap      integer;
  v_counter  integer;
  v_entries  integer;
BEGIN
  SELECT t.max_players, COALESCE(t.current_players, 0)
    INTO v_cap, v_counter
    FROM public.tournaments t
   WHERE t.id = p_tournament_id;

  IF NOT FOUND OR v_cap IS NULL OR v_cap <= 0 THEN
    RETURN false;                      -- uncapped: this function never refuses
  END IF;

  SELECT count(*) INTO v_entries
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;

  /* GREATEST, never the entry count alone: this can only ever be stricter than
     the counter test it replaces, never looser. */
  RETURN GREATEST(v_counter, COALESCE(v_entries, 0)) >= v_cap;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_update_managed_game(p_kind text, p_game_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_club uuid;
  v_players integer;
  v_status text;
  v_name text;
  v_sb numeric;
  v_bb numeric;
  v_min numeric;
  v_max numeric;
  v_seats integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF p_kind = 'table' THEN
    SELECT club_id, current_players, status
      INTO v_club, v_players, v_status
      FROM public.tables
     WHERE id = p_game_id
     FOR UPDATE;
  ELSIF p_kind = 'tournament' THEN
    SELECT club_id, current_players, status
      INTO v_club, v_players, v_status
      FROM public.tournaments
     WHERE id = p_game_id
     FOR UPDATE;
  ELSE
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_game_kind');
  END IF;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'game_not_found');
  END IF;
  IF NOT public.fn_can_create_games(v_club, v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;

  v_name := left(regexp_replace(COALESCE(p_patch ->> 'name', ''), '\s+', ' ', 'g'), 80);
  IF length(trim(v_name)) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'name_required');
  END IF;

  IF p_kind = 'table' THEN
    IF v_players > 0 OR lower(v_status) IN ('running', 'active') THEN
      UPDATE public.tables
         SET name = v_name, updated_at = now()
       WHERE id = p_game_id;
    ELSE
      SELECT COALESCE((p_patch ->> 'small_blind')::numeric, t.small_blind),
             COALESCE((p_patch ->> 'big_blind')::numeric, t.big_blind),
             COALESCE((p_patch ->> 'min_buy_in')::numeric, t.min_buy_in),
             COALESCE((p_patch ->> 'max_buy_in')::numeric, t.max_buy_in),
             COALESCE((p_patch ->> 'max_players')::integer, t.max_players)
        INTO v_sb, v_bb, v_min, v_max, v_seats
        FROM public.tables t
       WHERE t.id = p_game_id;

      IF v_sb IS NULL OR v_bb IS NULL OR v_min IS NULL OR v_max IS NULL OR v_seats IS NULL
         OR v_sb <= 0 OR v_bb < v_sb OR v_min <= 0 OR v_max < v_min THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'invalid_table_limits');
      END IF;

      UPDATE public.tables
         SET name = v_name,
             small_blind = v_sb,
             big_blind = v_bb,
             min_buy_in = v_min,
             max_buy_in = v_max,
             max_players = LEAST(10, GREATEST(2, v_seats)),
             updated_at = now()
       WHERE id = p_game_id;
    END IF;
  ELSE
    PERFORM 1
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_game_id
     FOR UPDATE;
    IF FOUND THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'players_registered');
    END IF;
    IF upper(v_status) NOT IN ('ANNOUNCED', 'REGISTERING', 'SCHEDULED') THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'already_started');
    END IF;

    UPDATE public.tournaments
       SET name = v_name,
           max_players = GREATEST(
             2,
             COALESCE((p_patch ->> 'max_players')::integer, max_players)
           ),
           start_time = COALESCE((p_patch ->> 'start_time')::timestamptz, start_time),
           updated_at = now()
     WHERE id = p_game_id;
  END IF;

  RETURN jsonb_build_object('ok', true);
END;
$function$
